L6_1.m_Talk_KOREA = "아무리 작전이라고 해도, 이건 좀 아닌 거 같지 않아요?"
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "いくら作戦だといっても、これは違うんじゃないですかね。"
L6_1.m_Talk_ENG = "Even for an operation, isn't this a bit too risky?"
L6_1.m_Talk_TWN = "雖說是作戰，但好像哪裡不太對？"
L6_1.m_Talk_THA = "แล้วอย่างนี้ปฏิบัติการจะไม่เสี่ยงเกินไปเหรอ?"
L6_1.m_Talk_VTN = "Ngay cả đối với một tác chiến, chẳng phải điều này hơi quá mạo hiểm sao?"
L6_1.m_Talk_SCN = "虽说是作战，但这也太冒险了吧？"
L6_1.m_Talk_DEU = "Ist das nicht selbst für eine Operation etwas zu riskant?"
L6_1.m_Talk_FRA = "N'est-ce pas un peu trop risqué, même pour une opération ?"
L7_1 = {}
L7_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 31612
L7_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L7_1.m_Pos = "R"
L7_1.m_Crash = 20
L7_1.m_Talk_KOREA = "괜히 이런 곳에 있다가, 저 고치를 자극해서 좋을 게 없다고 생각하는데요?"
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "こんなところに来てあの繭を刺激しても、何もいいことないですよ？"
L7_1.m_Talk_ENG = "If we lounge around here, we might end up provoking that cocoon."
L7_1.m_Talk_TWN = "我覺得我們待在這裡會刺激到那個繭，這對我們來說沒有任何好處。"
L7_1.m_Talk_THA = "ถ้าเรานั่งเล่นอยู่แบบนี้ เราอาจทำให้รังไหมเพิ่มขึ้นได้นะ"
L7_1.m_Talk_VTN = "Nếu lảng vảng như thế này, chúng ta có thể sẽ chọc tức cái kén đó."
L7_1.m_Talk_SCN = "我觉得我们待在这里会刺激到那个茧，这对我们来说是没有一点好处的。"
L7_1.m_Talk_DEU = "Wenn wir hier herumlungern, könnten wir am Ende noch diesen Kokon provozieren."
L7_1.m_Talk_FRA = "Si nous restons ici, nous pourrions finir par provoquer ce cocon et nous attirer des ennuis."
L8_1 = {}
