L9_1.m_Talk_KOREA = "그렇죠? 그럼 어서 여기서 벗어나자구요."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "ですよね？　それじゃあ、早くここから出ましょう。"
L9_1.m_Talk_ENG = "Right? Okay, then let's get out of here."
