L11_1.m_Pos = "C"
L11_1.m_Talk_KOREA = "거절하겠어요, 시영 씨. 왜냐하면…… 여기에 있다는 정보를 얻었거든요."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "お断りします、シノンさん。なぜなら……ここに存在するという情報を手に入れましたので。"
L11_1.m_Talk_ENG = "I refuse, Shiyoung. Because... I received intel, that it is here."
L11_1.m_Talk_TWN = "我拒絕。因為……據我得到情報所描述，東西就在這個地方。"
L11_1.m_Talk_THA = "ฉันขอโทษนะ ชิยอง” เพราะ...ฉันได้รับคำสั่งให้อยู่ที่นี่"
L11_1.m_Talk_VTN = "Tôi từ chối, Shiyoung. Bởi vì... tôi đã nhận được thông tin, nó ở đây."
L11_1.m_Talk_SCN = "我拒绝，时雨。因为……据我得到情报所描述，东西就在这个地方。"
L11_1.m_Talk_DEU = "Den Vorschlag muss ich leider ablehnen, Shiyoung. Ich ... habe nämlich eine Info erhalten, dass „es“ hier ist."
L11_1.m_Talk_FRA = "Impossible, Charlotte. Parce que... d'après mes informations... C'est ici."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@12#Talk"
L12_1.m_CutScenProcessKey = 12
