L12_1.m_Pos = "C"
L12_1.m_Talk_KOREA = "있다고요? 뭐가요? 설마 유령이?"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "存在する？　何がですか？　もしかして、幽霊？"
L12_1.m_Talk_ENG = "It? What's it? A ghost?"
L12_1.m_Talk_TWN = "就在這個地方？什麼東西？莫非是幽靈？"
L12_1.m_Talk_THA = "มัน? มันคืออะไรนะ? ผีหรอ?"
L12_1.m_Talk_VTN = "Nó? Cái gì vậy? Một con ma?"
L12_1.m_Talk_SCN = "就在这个地方？什么东西？莫非是幽灵？"
L12_1.m_Talk_DEU = "„Es“ ist hier? Was ist „es“? Ein Geist?"
L12_1.m_Talk_FRA = "C'est ici ? Mais quoi donc ? Le fantôme ?"
