L15_1.m_Bounce = L16_1
L15_1.m_Talk_KOREA = "아, 아니야! 이 세상에 유령 같은 건 없다고요! 장난치지 마세요, 시영 씨!"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "い、いいえ！　この世に幽霊なんていません！　からかわないでください、シノンさん！"
L15_1.m_Talk_ENG = "N-no! There's no such thing as ghosts! Stop joking around, Shiyoung!"
L15_1.m_Talk_TWN = "不，不！這個世界上才沒有幽靈！你別開玩笑了，時雨！"
L15_1.m_Talk_THA = "ม-ไม่! ไม่มีผีอะไรทั้งนั้น! เลิกล้อกันเล่นได้แล้ว ชิยอง!"
L15_1.m_Talk_VTN = "K-không! Không có thứ gì gọi là ma cả! Đừng đùa nữa, Shiyoung!"
L15_1.m_Talk_SCN = "不、不！这个世上才没有幽灵呢！你别开玩笑了，时雨！"
L15_1.m_Talk_DEU = "N-Nein! Es gibt doch gar keine Geister! Hör auf, Witze zu machen, Shiyoung!"
L15_1.m_Talk_FRA = "I-Impossible ! Les fantômes n'existent pas ! Arrêtez vos plaisanteries, Charlotte !"
