L18_1 = {}
L18_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 31612
