L18_1.m_Face = "UNIT_IDLE"
L18_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L18_1.m_Pos = "L"
L18_1.m_Talk_KOREA = "아무튼 제가 말하려던 건, 이곳 어딘가 소원을 이루어 주는 <color=#ffd34c>아티팩트</color>가 있다는 제보를 받았기 때문이에요."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "とにかく、私が言おうとしていたのは、ここのどこかに願いを叶えてくれる<color=#ffd34c>アーティファクト</color>があるという情報を得たからです。"
L18_1.m_Talk_ENG = "Well, what I was trying to say was that there's an <color=#ffd34c>Artifact</color> that grants wishes somewhere around here."
L18_1.m_Talk_TWN = "總之，我想說的是，我得到消息說在這地方的某處，有可以實現願望的<color=#ffd34c>人造神器</color>。"
L18_1.m_Talk_THA = "สิ่งที่ฉันอยากจะพูดคือมี <color=#ffd34c>อาร์ติแฟ็กต์</color> ที่ขอพรได้ที่ไหนสักแห่งแถวๆนี้"
L18_1.m_Talk_VTN = "Chà, điều tôi đang nói là có một <color=#ffd34c>Thần Khí</color> ban điều ước ở đâu đó quanh đây."
L18_1.m_Talk_SCN = "总之，我想说的是，我得到消息说在这地方的某处有可以实现愿望的<color=#ffd34c>人造神器</color>。"
L18_1.m_Talk_DEU = "Egal, ich wollte damit nur sagen, dass es irgendwo hier ein <color=#ffd34c>Artefakt</color> gibt, das Wünsche erfüllt."
L18_1.m_Talk_FRA = "Enfin bref, ce que j'essayais de dire, c'est que j'ai reçu l'information qu'un <color=#ffd34c>artefact</color> qui exauce les vœux se trouve ici."
