L21_1 = {}
L21_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 31612
L21_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_IDLE"
L21_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L21_1.m_Pos = "C"
L21_1.m_Talk_KOREA = "에이, 말도 안 돼. 그런 게 있으면 우리 세계가 이렇게 막장이 되었을 리 없잖아요."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "またまた。あり得ません。そんなものがあったら、私たちの世界はこんなに追い詰められてませんよ。"
L21_1.m_Talk_ENG = "No way. If that really existed, our world would never be this disastrous."
L21_1.m_Talk_TWN = "哈哈！騙人的吧？要是真有那種東西，那我們的世界也不至於變得這麼糟糕。"
L21_1.m_Talk_THA = "ไม่มีทาง หากสิ่งนั้นมีอยู่จริง โลกของเราก็คงไม่เกิดหายนะขนาดนี้"
L21_1.m_Talk_VTN = "Không đời nào. Nếu điều đó thực sự tồn tại, thế giới của chúng ta sẽ không bao giờ thảm khốc đến thế này."
L21_1.m_Talk_SCN = "哈哈！骗人的吧？要是真有那种东西，那我们的世界也不至于变得这么糟糕。"
L21_1.m_Talk_DEU = "Das kann doch gar nicht sein. Wenn es das wirklich gäbe, wäre unsere Welt niemals so chaotisch geworden."
L21_1.m_Talk_FRA = "N'importe quoi. Si une telle chose existait vraiment, notre monde ne serait pas dans cet état déplorable."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@22#Talk"
L22_1.m_CutScenProcessKey = 22
