L22_1.m_Crash = 10
L22_1.m_Talk_KOREA = "네. 하지만 충분히 검증해볼 필요는 있어요."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "はい。ですが、検証してみる必要はあると思います。"
L22_1.m_Talk_ENG = "Right, but it's still worth investigating."
L22_1.m_Talk_TWN = "嗯，不過，我們需要充分驗證一下。"
L22_1.m_Talk_THA = "ก็ใช่ แต่มันก็คุ้มไหมถ้าเราจะไปค้นหามัน"
L22_1.m_Talk_VTN = "Đúng, nhưng nó vẫn đáng để điều tra."
L22_1.m_Talk_SCN = "嗯，不过，我们需要充分验证一下。"
L22_1.m_Talk_DEU = "Mag sein, aber es lohnt sich trotzdem, der Sache auf den Grund zu gehen."
L22_1.m_Talk_FRA = "En effet. Mais cela vaut quand même la peine de vérifier."
