L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 31612
L25_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_IDLE"
L25_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L25_1.m_Pos = "L"
L25_1.m_Talk_KOREA = "우리가 찾는 아티팩트에는 <color=#ffd34c>원숭이 손</color>이라는 이름이 붙어 있다고 하니까요."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "私たちが探しているアーティファクトには、<color=#ffd34c>サルの手</color>という名前がついているらしいですから。"
L25_1.m_Talk_ENG = "It is said that the Artifact we're looking for is called the <color=#ffd34c>Monkey's Paw</color>."
L25_1.m_Talk_TWN = "我們要找的人造神器叫作<color=#ffd34c>猴爪</color>。"
L25_1.m_Talk_THA = "ได้ยินว่าอาร์ติแฟ็กต์ที่เรากำลังตามหามีชื่อว่า <color=#ffd34c>อุ้งมือลิง</color>"
L25_1.m_Talk_VTN = "Nghe nói Thần Khí mà chúng ta đang tìm kiếm có tên là <color=#ffd34c>Bàn Tay Khỉ </color>."
L25_1.m_Talk_SCN = "我们要找的人造神器叫做<color=#ffd34c>猴爪</color>。"
L25_1.m_Talk_DEU = "Man sagt, dass das Artefakt, nach dem wir suchen, <color=#ffd34c>Affenhand</color> genannt wird."
L25_1.m_Talk_FRA = "Apparemment, l'artefact que nous recherchons s'appelle la <color=#ffd34c>Patte de singe</color>."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 31612
L26_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_SURPRISE"
L26_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L26_1.m_Pos = "R"
L26_1.m_Crash = 30
L26_1.m_Talk_KOREA = "네? <color=#ffd34c>원숭이 손</color>?"
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "はい？　<color=#ffd34c>サルの手</color>？"
L26_1.m_Talk_ENG = "Huh? <color=#ffd34c>Monkey's Paw</color>?"
L26_1.m_Talk_TWN = "什麼？<color=#ffd34c>猴爪</color>？"
L26_1.m_Talk_THA = "หา? <color=#ffd34c>อุ้งมือลิง</color>หรอ?"
L26_1.m_Talk_VTN = "Huh? <color=#ffd34c>Bàn Tay Khỉ</color>?"
L26_1.m_Talk_SCN = "什么？<color=#ffd34c>猴爪</color>？"
L26_1.m_Talk_DEU = "Wie bitte? <color=#ffd34c>Affenhand</color>?"
L26_1.m_Talk_FRA = "Hein ? La <color=#ffd34c>Patte de singe</color> ?"
L27_1 = {}
L27_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 31612
L27_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_DESPAIR"
L27_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L27_1.m_Pos = "R"
L27_1.m_Talk_KOREA = "하하. 왠지 소원을 들어주긴 하는데, 요상한 방식으로 이루어 줄 것 같은 이름인데요?"
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "ハハ。なんだか願いを叶えてはくれるけど、変な形で叶えてくれそうな名前ですね。"
L27_1.m_Talk_ENG = "Ha ha. That sounds like a name that would grant wishes, but in a twisted way."
L27_1.m_Talk_TWN = "哈哈，感覺雖然能實現願望，但聽起來似乎會用奇怪的方法實現？"
L27_1.m_Talk_THA = "ฮ่า ฮา ฟังดูเหมือนชื่อของที่จะให้ความปรารถนา แต่ในทางที่เพี้ยนนะ"
L27_1.m_Talk_VTN = "Hà hà. Nghe cũng giống một cái tên mang lại điều ước, nhưng theo một cách khó hiểu."
L27_1.m_Talk_SCN = "哈哈，总感觉虽然能实现愿望，但听起来似乎会用奇怪的方法实现呢？"
L27_1.m_Talk_DEU = "Haha. Das klingt irgendwie schon nach einem Namen, der Wünsche erfüllt, wenn auch auf eine seltsame Art und Weise."
L27_1.m_Talk_FRA = "Ha ha. Ça sonne comme quelque chose qui exaucerait les vœux, mais d'une manière détournée."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 31612
L28_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L28_1.m_Pos = "L"
L28_1.m_Talk_KOREA = "시영 씨 말이 맞아요. 애초에 그런 효과 때문에 원숭이 손이라는 이름이 붙은 거죠."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "おっしゃるとおりです。そもそも、そんな効果があるからサルの手という名前がついたわけです。"
L28_1.m_Talk_ENG = "You're right. That's why it's called a Monkey's Paw in the first place."
L28_1.m_Talk_TWN = "你說的沒錯。就是因為那種效果，所以才會將它取名為猴爪。"
L28_1.m_Talk_THA = "เธอคิดถูก นั่นเป็นสาเหตุว่าทำไมจึงเรียกว่าอุ้งมือลิงตั้งแต่แรก"
L29_1 = "Đúng. Đó là lý do tại sao ngay từ đầu nó được gọi là Bàn Tay Khỉ."
L28_1.m_Talk_VTN = L29_1
L29_1 = "你说得没错。就是因为那种效果，所以才会将它取名为猴爪。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Du hast recht, Shiyoung. Genau deswegen wird es Affenhand genannt."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Tu as tout à fait raison. C'est pourquoi on appelle ça une Patte de singe d'ailleurs."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@29#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 29
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 31612
L29_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L29_1.m_Pos = "L"
L30_1 = "실제로 아티팩트가 어떻게 생겼는 지, 그게 어떤 물건인지는 아무도 모르지만요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "実際にアーティファクトがどんな形をしていて、どんなものなのかは誰も知らないそうですが。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "But no one knows what the Artifact looks like or what it actually is."
L29_1.m_Talk_ENG = L30_1
L30_1 = "實際上，誰也不知道這個人造神器長什麼樣子，是一個什麼樣的東西。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "แต่ไม่มีใครรู้ว่าอาร์ติแฟกต์นั้นมีหน้าตาเป็นยังไง"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nhưng không ai biết Thần Khí trông như thế nào và thực chất nó là gì."
L29_1.m_Talk_VTN = L30_1
L30_1 = "实际上，谁也不知道这个人造神器长什么样子，是一个什么样的东西。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Aber niemand weiß, wie das Artefakt aussieht oder was es tatsächlich ist."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Mais personne ne sait vraiment à quoi ressemble cet artefact ni ce qu'il est réellement."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 31612
L30_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_SURPRISE"
L30_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L30_1.m_Pos = "R"
L30_1.m_Crash = 30
L31_1 = "네? 그럼 어떻게 생긴 지도 모르는 물건을 찾는다는 말이에요?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "はい？　どんな形かも知らないものをどうやって探すんですか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "What? Then we're looking for something, and we don't even know what it looks like?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "什麼？我們要怎麼找一個不知道長怎樣的東西？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ว่าไงนะ? เท่ากับว่าเรากำลังหาบางสิ่งบางอย่างอยู่และเราเองก็ไม่รู้ด้วยซ้ำว่ามันหน้าตาเป็นยังงัยหรอ?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Cái gì? Thế chúng ta đang tìm thứ mà còn không biết nó trông như thế nào à?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "啊？那这个东西我们要怎么找？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Was? Dann suchen wir nach etwas, obwohl wir nicht einmal wissen, wie es aussieht?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Pardon ? Alors, nous cherchons un objet mais nous ne savons même pas à quoi il ressemble ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
