L32_1 = {}
L33_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 31612
L32_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "UNIT_PRIDE"
L32_1.m_Face = L33_1
L32_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L32_1.m_Pos = "C"
L33_1 = "믿기 힘든 이야기지만, 트레져헌터들 사이에서의 소문에 따르면, 아티팩트에는 <color=#ffd34c>보증서</color>가 같이 발굴되는 경우가 있다고 해요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "信じ難い話ですけど、トレジャーハンターの間で流れてる噂によると、アーティファクトは<color=#ffd34c>保証書</color>と一緒に発掘される場合があるそうです。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Believe it or not, according to the rumors among treasure hunters, Artifacts sometimes come with a <color=#ffd34c>warranty certificate</color>."
L32_1.m_Talk_ENG = L33_1
L33_1 = "雖然令人難以置信，但據貪婪的淘金者之間的傳聞，有時候人造神器會和<color=#ffd34c>保證書</color>一同被挖掘出來。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เธอเชื่อข่าวลือหรือปล่าว ที่ลือกันว่านักล่าสมบัติอาร์ติแฟกต์บางครั้งก็มาก้วยกันกับ<color=#ffd34c>ใบรับประกัน</color>"
L32_1.m_Talk_THA = L33_1
L33_1 = "Dù cô có tin hay không, theo tin đồn của những người săn kho báu, Thần Khí đôi khi đi kèm với <color=#ffd34c>giấy chứng nhận bảo đảm</color>."
L32_1.m_Talk_VTN = L33_1
L33_1 = "虽然令人难以置信，但据贪婪的淘金者之间的传闻，有时候人造神器会和<color=#ffd34c>保证书</color>一同被挖掘出来。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Es mag zwar schwer zu glauben sein, aber Gerüchten von Schatzsuchern zufolge werden Artefakte manchmal mit einer <color=#ffd34c>Garantie</color> ausgegraben."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Croyez-le ou non, mais selon les rumeurs qui circulent parmi les chasseurs de trésors, les artefacts sont parfois découverts avec un <color=#ffd34c>certificat de garantie</color>."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
