L33_1.m_Crash = 20
L34_1 = "그 보증서에는 아티팩트의 명칭과 효과…… 그리고 뭐였더라?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "その保証書には、アーティファクトの名称と効果……それから、ええと。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "That warranty is said to contain the Artifact's name, effect, and... what was it?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "保證書上寫著人造神器的名稱和效果……還有什麼來著？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "การรับประกันนั้นมีชื่ออาร์ติแฟกต์ เอฟเฟค และ... ว่ามันคืออะไร?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Lời bảo đảm đó được cho là bao gồm tên, tác dụng của Thần Khí và... nó là gì?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "保证书上写着人造神器的名称和效果……还有什么来着？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Diese Garantie soll den Namen des Artefakts, seine Wirkung und ... was war es nochmal?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Ce certificat contiendrait le nom, l'effet de l'artefact et... quoi d'autre déjà...?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 31612
L34_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_IDLE"
L34_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L34_1.m_Pos = "C"
L35_1 = "<color=#ffd34c>여기까지 도달한 걸 축하한다, 2등</color>이였던가? 아무튼 괴상한 메시지가 적혀 있다고 해요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "<color=#ffd34c>ここまでよくたどり着いたな。おめでとう、2位</color>だったかな？　とにかく、変なメッセージが書いてあるらしいです。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "A weird message that reads, \"<color=#ffd34c>Congratulations on coming in second,</color>\" or something."
L34_1.m_Talk_ENG = L35_1
L35_1 = "好像是<color=#ffd34c>恭喜你到達這裡，第二名</color>之類的奇怪文字。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ข้อความแปลกๆ เขียนว่า \"<color=#ffd34c>ขอแสดงความยินดีด้วยในการมาเป็นอันดับสอง</color>\" หรืออะไรสักอย่าง"
L34_1.m_Talk_THA = L35_1
L35_1 = "Một tin nhắn kỳ lạ có nội dung \"<color=#ffd34c>Xin chúc mừng bạn đã về nhì,</color>\" hay gì đó."
L34_1.m_Talk_VTN = L35_1
L35_1 = "好像是<color=#ffd34c>“恭喜你到达这里，第二名”</color>之类的奇怪信息。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Dort soll eine komische Nachricht gestanden haben. So etwas in der Art wie: „<color=#ffd34c>Gratulation zum zweiten Platz</color>“."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Un message étrange qui dirait <color=#ffd34c>Félicitations pour votre seconde place</color>, ou quelque chose dans le genre."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
