L38_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 31612
L37_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_DESPAIR"
L37_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L37_1.m_Pos = "R"
L37_1.m_Crash = 20
L38_1 = "하하, 정말로 변변치 못한 정보네요, 그거."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ハハ、本当につまらない情報ですね、それ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Ha ha, that's pretty useless information."
L37_1.m_Talk_ENG = L38_1
L38_1 = "哈哈，這個情報有點弱欸。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ฮ่าฮ่า นั่นเป็นข้อความที่ไร้สาระมาก"
L37_1.m_Talk_THA = L38_1
L38_1 = "Ha ha, đó là thông tin khá vô ích."
L37_1.m_Talk_VTN = L38_1
L38_1 = "哈哈，这个情报其实不怎么样啊。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Haha, das sind ziemlich nutzlose Informationen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Ha ha, quelle information inutile."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 31612
L38_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L38_1.m_Pos = "L"
L39_1 = "아무튼 이곳에 아티팩트가 있다면, 찾아볼 가치는 분명히 있어요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "とにかくここにアーティファクトがあるなら、探してみる価値は十分あります。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Whatever the case, if there's an Artifact here, it's definitely worth searching for."
L38_1.m_Talk_ENG = L39_1
L39_1 = "總之，如果這個地方真有人造神器，那還是很有尋找的價值。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ไม่ว่ายังไงก็ตาม หากมีอาร์ติแฟกต์อยู่ที่นี่ มันก็ต้องคุ้มค่าในการค้นหาอย่างแน่นอน"
L38_1.m_Talk_THA = L39_1
L39_1 = "Dù thế nào đi nữa, nếu có một Thần Khí ở đây thì nó chắc chắn đáng để tìm kiếm."
L38_1.m_Talk_VTN = L39_1
L39_1 = "总之，如果这个地方真有人造神器，那还是很有寻找的价值。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Wie auch immer, wenn es hier wirklich ein Artefakt gibt, lohnt es sich auf jeden Fall, danach zu suchen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Quoi qu'il en soit, s'il y a un artefact ici, ça vaut vraiment la peine de chercher."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 31612
L39_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L39_1.m_Pos = "L"
L40_1 = "이상한 방식으로 이루어 준다고는 하지만, 어쨌든 소원을 이루어 주는 강력한 아티팩트니까요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "変な方法で叶えてくれるとは言いますけど、とにかく願いを叶えてくれる強力なアーティファクトですから。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Even if it works in a twisted way, it's still a powerful Artifact that grants your wishes."
L39_1.m_Talk_ENG = L40_1
L40_1 = "雖說會用奇怪的方式實現願望，但總歸來說是可以實現願望的強大人造神器。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "แม้ว่ามันจะทำงานในลักษณะที่ผิดเพี้ยนแต่มันก็ยังเป็นอาร์ติแฟกต์ที่ทรงพลังที่จะให้พรแก่เธอ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Ngay cả khi nó hoạt động theo một cách khó hiểu, nó vẫn là một Thần Khí mạnh mẽ có thể đáp ứng mong muốn."
L39_1.m_Talk_VTN = L40_1
L40_1 = "虽说会用奇怪的方式实现愿望，但总归来说是可以实现愿望的强大人造神器。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Auch wenn es auf eine komische Weise funktioniert, ist es immer noch ein mächtiges Artefakt, das Wünsche erfüllen kann."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Même s'il fonctionne de manière étrange, il s'agit tout de même d'un artefact puissant qui exauce les vœux."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@40#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 40
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 31612
L40_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "UNIT_PRIDE"
L40_1.m_Face = L41_1
L40_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L40_1.m_Pos = "L"
L40_1.m_Crash = 20
L41_1 = "엉뚱한 사람이 관리하는 것보다, 군에서 관리하는 편이 믿음직스럽겠죠."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "とんでもない人が管理するより、軍で管理した方が安心でしょう。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "It would be more trustworthy in the hands of the military, rather than in the hands of a stranger."
L40_1.m_Talk_ENG = L41_1
L41_1 = "與其交給莫名其妙的人來管理，還不如交由部隊更可靠些吧。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "มันจะดูมีค่ามากหากมันได้มาอยู่ในมือของทหาร ดีกว่าตกอยู่ในกำมือของใครก็ไม่รู้"
L40_1.m_Talk_THA = L41_1
L41_1 = "Nó sẽ đáng tin cậy hơn trong tay quân đội, hơn là trong tay người lạ."
L40_1.m_Talk_VTN = L41_1
L41_1 = "与其交给莫名其妙的人来管理，还不如交由部队更可靠些吧。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Es wäre besser, wenn es in den Händen des Militärs landen würde als in den Händen irgendeines Fremden."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Il serait plus en sécurité entre les mains de l'armée, plutôt que dans celles d'un maniaque."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
