L42_1 = {}
L43_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 31612
L42_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_SURPRISE"
L42_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L42_1.m_Pos = "C"
L42_1.m_Crash = 20
L43_1 = "어라라, 글쎄요?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "あれれ、どうでしょう？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Oh, I'm not sure."
L42_1.m_Talk_ENG = L43_1
L43_1 = "呃呃，這個嘛？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "โอ้ะ ฉันไม่รู้เกี่ยวกับเรื่องนั้นเลย"
L42_1.m_Talk_THA = L43_1
L43_1 = "Ồ, tôi không biết đấy."
L42_1.m_Talk_VTN = L43_1
L43_1 = "呃呃，这个嘛？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Äh, ich bin mir da nicht so sicher."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Oh, je n'en suis pas si sûre."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 31612
L43_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_Face = "UNIT_IDLE"
L43_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L43_1.m_Pos = "C"
L44_1 = "영화 같은 데서 보면, 꼭 카린 양 같은 고지식하고, 앞뒤 꽉 막힌 사람이 대의를 위한다면서 소원을 잘못 빌었다가 대참사가 일어나지 않나요?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "映画とかで見ると、カリンさんのような生真面目で融通の利かない人が、大儀のためと言いながら間違った願い事をして、大惨事が起きたりするじゃないですか。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "In movies, doesn't someone as strict and inflexible as you normally wish for the wrong thing \"for the greater good\" and end up causing a catastrophe?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "如果這是電影裡的劇情，像卡琳你這樣固執又死腦筋的人，會發生打著正義的旗幟許錯願望，導致發生悲劇的事情吧？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ในหนัง ไม่มีใครที่แข็งแกร่งและมั่นคง กับคำขอทำสิ่งที่ผิด “เพื่อสิ่งที่ดียิ่งขึ้น” แล้วสุดท้ายก็ทำให้เกิดหายนะ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Trong phim, chẳng phải ai đó nghiêm khắc và thiếu linh hoạt như cô thường mong muốn điều sai trái “vì điều tốt đẹp hơn” và cuối cùng là gây ra thảm họa sao?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "如果这是电影里的剧情，像卡琳你这样固执又死脑筋的人，会发生打着大义的名号许错愿望，导致发生悲剧的事情吧？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Wünschen sich in Filmen nicht so strenge und sture Personen wie du, oft das Falsche „zum Wohle der Allgemeinheit“ und verursachen somit am Ende eine Katastrophe?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Dans les films, les personnages aussi stricts et inflexibles que vous ne font-ils pas le mauvais vœu pour « le bien commun » et ne finissent-ils pas par causer une catastrophe, en général ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 31612
L44_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L44_1.m_Pos = "C"
L44_1.m_Crash = 30
L45_1 = "설마, 그런 수상쩍은 물건으로 우리 세계의 멸망을 막아 달라는 소원을 빌지는 않겠죠?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "まさか、そんな怪しいもので私たちの世界の滅亡を止めてくれとか願ったりしないですよね？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You wouldn't ask that sketchy thing for our world to be saved from doom, right?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "你不會用那個奇怪的東西，祈求阻止我們的世界滅亡吧？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เธอจะไม่ขอให้โลกของเรารอดพ้นจากหายนะ หรอ ?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cô sẽ không yêu cầu thứ sơ sài đó để thế giới của chúng ta được cứu khỏi sự diệt vong, phải không?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "你不会用那个奇怪的东西，祈求阻止我们的世界灭亡吧？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Du hast doch nicht vor, dieses seltsame Ding darum zu bitten, unsere Welt vor dem Untergang zu bewahren, oder?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "J'espère que vous ne ferez pas le vœu d'empêcher l'annihilation de notre monde à cet artefact suspect, tout de même ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
