L48_1 = "흥! 절 대체 어떻게 생각하는 거예요?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "フン！　いったい私をなんだと思っているのですか？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Hmph! Who do you think I am?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "哼！你把我當成什麼人啦！"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฮึ่ม! เธอคิดว่ายังไงกับฉันล่ะ?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Hừm! Cô nghĩ tôi là ai?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "哼！你把我想成什么人了！"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Hmpf! Was glaubst du eigentlich, wer ich bin?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Pff ! Pour qui me prenez-vous ?"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@48#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 31612
L48_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_HATE"
L48_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L48_1.m_Pos = "L"
L49_1 = "아티팩트 같은 엄청난 물건을 사적인 목적으로 쓸 생각은 없어요!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "アーティファクトのようなすごいものを、私的な目的に使うつもりはありません！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I would never use something as great as an Artifact to fulfill my personal desires!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "我才不會把人造神器這麼厲害的東西用在私人目的上！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ฉันจะไม่มีวันใช้บางสิ่งที่ยิ่งใหญ่กับอาร์ติแฟกต์เพื่อเติมเต็มความปรารถนาส่วนตัวของตัวเอง!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tôi sẽ không bao giờ sử dụng thứ gì đó tuyệt vời như Thần Khí để thực hiện mong muốn cá nhân của mình!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "我才不会把人造神器这么了不起的东西用在私人目的上！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ich habe nicht die Absicht, etwas so Großartiges wie ein Artefakt für meine persönlichen Zwecke zu verwenden!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Je n'utiliserais jamais quelque chose d'aussi important qu'un artefact à des fins personnelles !"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@49#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 31612
L49_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L49_1.m_Pos = "L"
L50_1 = "그리고 따지고 보면…… 저보다 시영 씨 같은 사람한테 아티팩트가 넘어가는 게 더 큰 일 아닌가요?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "それに考えてみたら……私よりシノンさんみたいな人の手にアーティファクトが渡る方がもっと危険なのでは？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "And realistically... wouldn't it be worse if the Artifact were to fall into the hands of someone like you, Shiyoung?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "而且真要說起來……把人造神器交給像你這樣的人反而更糟糕吧？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ความเป็นจริงแล้ว... มันจะไม่แย่ไปกว่านี้เหรอถ้าอาร์ติแฟกต์ตกไปอยู่ในมือของคนอย่างเธอชิยอง?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Và thực tế mà nói... chẳng phải sẽ tệ hơn nếu Thần Khí rơi vào tay một người như cô sao, Shiyoung?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "而且细究起来……把人造神器交给你这样的人反而更糟糕吧？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Und wenn ich so darüber nachdenke ... wäre es nicht schlimmer, wenn das Artefakt in die Hände von jemandem wie dir fallen würde, Shiyoung?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Et puis, si on y réfléchit... Ne serait-ce pas encore pire qu'un tel artefact tombe entre les mains de quelqu'un comme vous, Charlotte ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@50#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 31612
