L51_1 = "네? 제가 왜요? 저 같이 욕심 없는 사람이 또 어디 있다고 그래요?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "はい？　どうしてですか？　私ほど欲のない人もいないと思いますが。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Huh? What's wrong with me? I'm such a selfless person."
L50_1.m_Talk_ENG = L51_1
L51_1 = "我？我怎樣？還有人像我這樣無欲無求嗎？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ฮะ? ฉันมีอะไรที่ไม่ดีหรอ? ฉันคือผู้ที่เสียสละนะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Hử? Tôi thì sao? Tôi là một người vị tha."
L50_1.m_Talk_VTN = L51_1
L51_1 = "我？我怎么了？还有人像我这样无欲无求吗？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Hä? Was wäre daran denn so schlimm? Ich bin doch so ein selbstloser Mensch."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Hein ? Qu'est-ce qui ne va pas chez moi ? Je suis une personne tout à fait altruiste."
L50_1.m_Talk_FRA = L51_1
