L2_1 = "혹시라도 제가 카린 양보다 먼저 아티팩트를 찾는다고 해도, 저어얼~대 먼저 쓸 생각이 없답니다?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "仮に私がカリンさんより先にアーティファクトを見つけたとしても、絶～対に先に使うつもりはないですよ？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Even if I find the Artifact before you do, I would neeeeever use it first."
L1_1.m_Talk_ENG = L2_1
L2_1 = "就算我比卡琳先找到人造神器，我也絕～對不會擅自使用的喔？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ถึงฉันจะพบอาร์ติแฟกต์ก่อน ที่เธอจะพบ แต่ฉันก็ไม่คิดจะใช้มันก่อน"
L1_1.m_Talk_THA = L2_1
L2_1 = "Ngay cả khi tôi tìm thấy Thần Khí trước cô, tôi sẽ không bao giờ sử dụng nó trước."
L1_1.m_Talk_VTN = L2_1
L2_1 = "哪怕我比卡琳你先找到人造神器，我也绝~对不会擅自使用的噢？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Selbst wenn ich das Artefakt finde, bevor du es tust, würde ich es niemals zuerst verwenden."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Même si je trouvais l'artefact avant vous, jamais, au grand JAMAIS, je ne m'en servirais la première."
