L8_1 = "그러고보니, 시영 씨. 아까 새끼 발톱이 아프다고 하셨죠?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "そういえば、シノンさん。さっき、足の小指の爪が痛いとか言っていましたよね？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Oh, by the way, Shiyoung. You mentioned that your pinky toenail was hurting."
L7_1.m_Talk_ENG = L8_1
L8_1 = "不過時雨，你剛才不是說腳的小拇指痛嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "โห้ เอาเถอะะ ชิยอง เธอบอกว่าเจ็บที่เล็บเท้านิ้วก้อยของเธออยู่ "
L7_1.m_Talk_THA = L8_1
L8_1 = "Ồ, nhân tiện, Shiyoung. Cô đã nói là móng chân út đang bị đau."
L7_1.m_Talk_VTN = L8_1
L8_1 = "对了，时雨。你提到过你的小脚趾甲疼是吧？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Übrigens, Shiyoung. Hast du nicht gemeint, dass dein kleiner Zehennagel weh tut?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Oh, au fait, Charlotte. Vous aviez bien dit que l'ongle de votre petit orteil vous faisait souffrir, n'est-ce pas ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 31612
L8_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L8_1.m_Pos = "L"
L9_1 = "오늘은 이쯤하고 먼저 들어가시는 게 어때요?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "今日はこのくらいにして、先に帰ったらどうですか？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "How about you wrap it up here and head home?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "那今天就到此為止，要不你先回去？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แล้วเธอจะทำแผลยังไงที่นี่ กลับบ้านดีไหม?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Hay là cô xong việc rồi về nhà trước?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "那今天就到此为止，要不你先回去？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Wie wäre es, wenn du für heute Schluss machst und schon mal nach Hause gehst?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Que diriez-vous de vous arrêter ici et de rentrer chez vous ?"
L8_1.m_Talk_FRA = L9_1
