L19_1 = "카린 양? 아무래도 보증서가 딸려 있다는 힌트 하나로는 부족한 거 같은데……."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "カリンさん？　やっぱり保証書付きっていうヒントだけでは足りないと思うんですけど……"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Karin? The fact that it has a warranty certificate is not enough of a clue..."
L18_1.m_Talk_ENG = L19_1
L19_1 = "卡琳？單憑人造神器有保證書這一個提示是遠遠不夠的……"
L18_1.m_Talk_TWN = L19_1
L19_1 = "คาริน? ที่ว่าการมีใบรับประกันมันยังไม่เพียงพอนะ..."
L18_1.m_Talk_THA = L19_1
L19_1 = "Karin? Việc nó có giấy bảo hành cũng chưa đủ manh mối..."
L18_1.m_Talk_VTN = L19_1
L19_1 = "卡琳？仅凭人造神器有保证书这一个提示是远远不够的……"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Karin? Die Tatsache, dass es eine Garantie hat, ist kein ausreichender Hinweis ..."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Karin ? Le fait qu'il ait un certificat de garantie ne suffit pas comme seul indice..."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@69#Talk"
