L19_1.m_Pos = "C"
L20_1 = "혹시, 저 몰래 힌트 한 두개 더 가지고 있는 거 아니에요?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "もしかして、私には内緒でヒントをもっと持ってたりしません？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Are you hiding other clues or something?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "你是不是瞞著我？其實還有其他一、二個提示？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "เธอกำลังซ่อนเบาะแสอื่น ๆ หรืออะไรบางอย่างอยู่ไหม?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Cô đang che giấu manh mối khác hay gì à?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "你不会是瞒着我吧？是不是还有一两个提示？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Vielleicht versteckt es ja noch ein oder zwei andere Hinweise?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Vous ne me cachez pas d'autres indices, hein ?"
L19_1.m_Talk_FRA = L20_1
