L23_1 = "L_M_I"
L22_1.m_Pos = L23_1
L23_1 = "좀 더 진지하게 작전에 임해줄 순 없어요? 이건 보물 찾기가 아니라고요!"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "もっと真面目に作戦に取り掛かってもらえませんか？　これは宝探しではないんですよ！"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Would you take this operation more seriously? This isn't a treasure hunt!"
L22_1.m_Talk_ENG = L23_1
L23_1 = "你就不能認真對待這次作戰嗎？這不是尋寶遊戲！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เธอจะปฏิบัติการนี้อย่างจริงจังมากขึ้นใช่ไหม? นี่ไม่ใช่การออกล่าสมบัตินะ!"
L22_1.m_Talk_THA = L23_1
L23_1 = "Cô thực hiện tác chiến nghiêm túc hơn được không? Đây đâu phải là  săn tìm kho báu đâu!"
L22_1.m_Talk_VTN = L23_1
L23_1 = "你就不能认真对待这次作战吗？这不是寻宝游戏！"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Würdest du diese Operation bitte mal ein wenig ernster nehmen? Das ist schließlich keine Schatzsuche!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Vous devriez prendre cette opération plus au sérieux ! Ce n'est pas une chasse au trésor !"
L22_1.m_Talk_FRA = L23_1
