L24_1 = "보물찾기 맞는 거 같은데? 전 오히려 어렸을 때 생각나고 좋은데요?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "宝探しですよ、どう見ても。私はむしろ子どもの頃が思い出されて楽しいですけど？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "It sure seems like one. I like it. It reminds me of my childhood."
L23_1.m_Talk_ENG = L24_1
L24_1 = "就是尋寶遊戲吧？還讓我想起小時候，很開心呢？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ดูเหมือนว่าฉันกำลังคิดแบบนั้น ฉันชอบนะ มันทำให้ฉันนึกถึงวัยเด็กน่ะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Nó chắc chắn có vẻ giống như vậy. Tôi thích nó. Nó làm tôi nhớ đến tuổi thơ."
L23_1.m_Talk_VTN = L24_1
L24_1 = "怎么不是寻宝游戏了？反而让我想起了小时候，感觉很不错呢？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Es scheint aber eine zu sein. Das erinnert mich total an meine Kindheit."
L23_1.m_Talk_DEU = L24_1
L24_1 = "En tout cas, on en dirait une. J'aime ça. Ça me rappelle mon enfance."
L23_1.m_Talk_FRA = L24_1
