L26_1.m_fTalkTime = 0.03
L27_1 = "それで……そろそろ言ってくれてもいいんじゃないですか？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "So... Isn't it about time you told me the truth?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "所以……現在可以告訴我了吧？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เอาล่ะ... ถึงเวลาที่เธอจะต้องบอกความจริงกับฉันแล้วนะ?"
