L26_1.m_Talk_VTN = L27_1
L27_1 = "所以……现在可以告诉我了吧？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Also ... Ist es nicht langsam mal an der Zeit, dass du mir die Wahrheit sagst?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Bon... Et si vous me disiez la vérité, maintenant ?"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 31612
L27_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L27_1.m_Pos = "C"
L28_1 = "카린 양이 만약 아티팩트를 손에 넣는다면, 어떤 소원을 빌고 싶으세요?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "もしカリンさんがアーティファクトを手に入れたら、何を願いたいんですか？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "If you find the Artifact, what wish are you going to make?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "如果卡琳你找到人造神器，你準備許什麼願望？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "หากเธอเจออาร์ติแฟกต์ เธอจะอธิษฐานอะไร?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Nếu tìm thấy Thần Khí, cô sẽ ước gì?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "如果卡琳你找到了人造神器，你准备许什么愿望？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Was würdest du dir wünschen, falls du das Artefakt finden solltest?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Si vous trouviez l'artefact, que feriez-vous ?"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@78#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 78
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 31612
L28_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
