L28_1.m_Pos = "C"
L28_1.m_Crash = 20
L29_1 = "아까 듣기로는 개인적으로 쓸 생각은 없다고 했죠?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "さっきは個人的に使うつもりはないって言ってましたよね？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "You mentioned that you didn't want to use it for personal desires."
L28_1.m_Talk_ENG = L29_1
L29_1 = "你剛剛說，不會用於私人目的對吧？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เธอบอกว่าเธอไม่ต้องการใช้มันเพื่อเติมเต็มความปรารถนาส่วนตัว"
L28_1.m_Talk_THA = L29_1
L29_1 = "Cô đã nói là cô không muốn ước cho mong muốn cá nhân."
L28_1.m_Talk_VTN = L29_1
L29_1 = "你刚刚说，不会用于私人目的对吧？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Du hast vorhin gesagt, dass du es nicht für persönliche Zwecke verwenden würdest."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Vous avez dit que vous ne vouliez pas l'utiliser à des fins personnelles."
L28_1.m_Talk_FRA = L29_1
