L32_1 = "패스파인더 작전 이후, 저는 줄곧 생각해왔어요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "パスファインダー作戦から、私はずっと考えていました。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "After Operation Pathfinder, I've been thinking."
L31_1.m_Talk_ENG = L32_1
L32_1 = "十字路口作戰之後，我就一直在想……"
L31_1.m_Talk_TWN = L32_1
L32_1 = "หลังจากปฏิบัติการผู้หาเส้นทาง ฉันกำลังคิดว่า"
L31_1.m_Talk_THA = L32_1
L32_1 = "Sau Chiến dịch Người Tìm Đường, tôi đã suy nghĩ rất nhiều."
L31_1.m_Talk_VTN = L32_1
L32_1 = "十字路口作战之后，我就一直在想……"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Nach dem Operation „Wegfinder“ habe ich die ganze Zeit darüber nachgedacht."
L31_1.m_Talk_DEU = L32_1
L32_1 = "J'ai beaucoup réfléchi après l'opération Éclaireur."
L31_1.m_Talk_FRA = L32_1
