L33_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 31612
L32_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_IDLE"
L32_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L32_1.m_Pos = "C"
L32_1.m_Crash = 20
L33_1 = "시영 씨를 닮은 그 소년은 말했죠."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "シノンさんに似たあの少年が言っていましたよね。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "That boy, who looks like you, said something."
L32_1.m_Talk_ENG = L33_1
L33_1 = "那個和長得時雨很像的男孩說過的話。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เด็กผู้ชายคนนั้นที่ดูเหมือนเธอกำลังพูดอะไรบางอย่าง"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cậu bé mà trông giống cô, đã nói rằng.."
L32_1.m_Talk_VTN = L33_1
L33_1 = "那个和时雨很像的男孩子曾说过的话。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Dieser Junge, der genau wie du aussieht, hat etwas gesagt."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Ce garçon, qui vous ressemble, a dit quelque chose."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 31612
L33_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L33_1.m_Pos = "C"
L34_1 = "우리 세계와 그쪽 세계의 기술 격차는 <color=#ffd34c>관리국</color>이라는 조직 때문이라고……."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "私たちの世界とあちらの世界の技術の差は、<color=#ffd34c>管理局</color>という組織のせいだって……"
L33_1.m_Talk_JPN = L34_1
L34_1 = "That the disparity between our world and their world's technology comes from an organization called <color=#ffd34c>the Administration</color>..."
L33_1.m_Talk_ENG = L34_1
L34_1 = "我們世界和他們世界之所以有技術差距，是因為那個叫<color=#ffd34c>管理局</color>的組織……"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ความแตกต่างระหว่างโลกของเราและเทคโนโลยีของโลกของพวกเขานั้นมาจากสถาบันที่เรียกว่า <color=#ffd34c>องค์การบริหารโลก</color>..."
L33_1.m_Talk_THA = L34_1
L34_1 = "Rằng sự chênh lệch giữa thế giới của chúng ta và công nghệ của thế giới họ xuất phát từ một tổ chức có tên là <color=#ffd34c>Cục Quản Lý</color>..."
L33_1.m_Talk_VTN = L34_1
L34_1 = "我们世界和他们世界之所以有技术差距，是因为那个叫<color=#ffd34c>管理局</color>的组织……"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Die technologische Kluft zwischen unserer Welt und dieser Welt ist auf eine Organisation namens <color=#ffd34c>Administration</color> zurückzuführen ..."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Il a dit que la disparité qui existe entre les technologies de nos deux mondes viendrait de l'organisation appelée l'<color=#ffd34c>Administration</color>..."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
