L38_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 31612
L37_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_IDLE"
L37_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L37_1.m_Pos = "L"
L38_1 = "정말로 우리 세계에 관리국이라는 조직이 없어서 이런 결과에 도달한 거라면……."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "本当に私たちの世界に管理局という組織がなくてこんな結果に到達したのなら……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "If the state of our world is due to the absence of the Administration..."
L37_1.m_Talk_ENG = L38_1
L38_1 = "如果我們世界真的是因為沒有管理局這種組織，才走向這種結局……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "หากสภาวะโลกของเราเกิดการขาดปกครองจากองค์การบริหารโลก..."
L37_1.m_Talk_THA = L38_1
L38_1 = "Nếu tình trạng thế giới của chúng ta là do sự vắng mặt của Cục Quản Lý..."
L37_1.m_Talk_VTN = L38_1
L38_1 = "如果我们世界真的是因为没有管理局这种组织，所以最终走向了这种结果……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Wenn der Zustand unserer Welt auf die Abwesenheit der Administration zurückzuführen ist ..."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Si l'état de notre monde est dû à l'absence de l'Administration..."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 31612
L38_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L38_1.m_Pos = "L"
L39_1 = "반대로 지금이라도 우리 세계의 관리국 기술을 적용할 수 있다면 어떻게 될까요?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "逆に、今からでも私たちの世界に管理局の技術を適用できたならどうでしょうか？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "What would happen if we were to apply the Administration's technology to our world?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "那反過來，如果把管理局的技術應用在我們世界，那會怎麼樣呢？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "จะเกิดอะไรขึ้นถ้าเรานำเทคโนโลยีขององค์การบริหารโลกมาประยุกต์ใช้กับโลกของเราล่ะ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Điều gì sẽ xảy ra nếu chúng ta áp dụng công nghệ của Cục Quản Lý vào thế giới của mình?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "那么相反，如果现在我们把管理局的技术应用在我们世界，那会怎么样呢？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Was würde dann passieren, wenn wir die Technologie der Administration auf unsere Welt anwenden würden?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Que se passerait-il si nous implémentions la technologie de l'Administration à celui-ci ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 31612
L39_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L39_1.m_Pos = "L"
L39_1.m_Crash = 20
L40_1 = "우리 세계의 멸망을 늦출……. 아니, 적어도 그때처럼 무력하게 주변 사람을 잃는 결과는 막을 수 있지 않을까요?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "私たちの世界の滅亡を遅らせる……いいえ、少なくともあの時のように、なす術もなく周りの人を失う結果だけは止められるのではないでしょうか？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Maybe we could postpone the end of our world–or, rather, maybe we could prevent a future where we lose our beloved so helplessly."
L39_1.m_Talk_ENG = L40_1
L40_1 = "是不是就可以推遲我們世界的滅亡……不，至少可以阻止像那時一般無力地失去身邊人的結果吧？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "บางทีเราอาจเลื่อนการเวลาการสิ้นสุดโลกของเราออกไปได้ หรือบางทีเราอาจป้องกันไม่ให้อนาคตที่เราสูญเสียคนที่รักเกิดขึ้น"
L39_1.m_Talk_THA = L40_1
L40_1 = "Có lẽ chúng ta có thể trì hoãn ngày tận thế của mình – hay nói đúng hơn, có lẽ chúng ta có thể ngăn chặn một tương lai nơi chúng ta mất đi người mình yêu thương một cách bất lực."
L39_1.m_Talk_VTN = L40_1
L40_1 = "是不是就可以推迟我们世界的灭亡……不，至少我们可以阻止像那时一般无力地失去身边人的结果吧？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Vielleicht könnten wir das Ende unserer Welt hinauszögern – oder zumindest könnten wir verhindern, dass die von uns geliebten Menschen genauso hilflos von uns gehen wie damals."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Peut-être que nous pourrions retarder la fin de notre monde... Ou peut-être même que nous pourrions empêcher un futur où nous perdrions nos êtres chers de manière inexorable."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 31612
L40_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L40_1.m_bWaitClick = true
