L42_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 31612
L41_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L41_1.m_Pos = "R"
L42_1 = "지난 작전에서 우리가 그 세계에 닿을 수 있었던 것은 순전히 우연이었잖아요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "前の作戦で私たちがあの世界に行けたのは、偶然だったじゃないですか。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "It was merely a coincidence that we were able to reach that world in our previous operation."
L41_1.m_Talk_ENG = L42_1
L42_1 = "在上一次作戰中我們能到達那個世界，完全是因為巧合。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "มันเป็นเพียงเรื่องบังเอิญที่เราเข้าไปถึงโลกนั้นได้ในปฏิบัติการครั้งก่อนของเรา"
L41_1.m_Talk_THA = L42_1
L42_1 = "Việc chúng ta có thể đến được thế giới đó trong tác chiến trước đó chỉ là sự trùng hợp ngẫu nhiên mà thôi."
L41_1.m_Talk_VTN = L42_1
L42_1 = "在上一次作战中我们能到达那个世界，完全是因为巧合。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Es war lediglich ein Zufall, dass wir diese Welt in unserer vorherigen Operation erreichen konnten."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Ce n'était qu'une simple coïncidence si nous avons pu atteindre ce monde lors de notre opération précédente."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@92#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 92
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 31612
L42_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L42_1.m_Pos = "R"
L42_1.m_Crash = 30
L43_1 = "그 뒤로도 몇 번인가 저쪽 세계로 불려가긴 했지만…… 그건 저희의 의지가 아니었고요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "その後も何度かあっちの世界に呼び出されていきましたけど……それは私たちの意志ではなかったですし。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "We did get sent to that world a few times after that, but... we had no say in that."
L42_1.m_Talk_ENG = L43_1
L43_1 = "在那之後，雖然又去過很多次那個世界……但那並不是因為我們自己的意志。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เราถูกส่งไปยังโลกนั้นในเวลาสั่นๆ ... แต่เราไม่ได้พูดอะไรกันในนั้น"
L42_1.m_Talk_THA = L43_1
L43_1 = "Chúng ta đã được gửi đến thế giới đó vài lần sau đó, nhưng... Lại không có nói về việc đó."
L42_1.m_Talk_VTN = L43_1
L43_1 = "在那之后，虽然又去过很多次那个世界……但那并不是因为我们自己的意志。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Danach wurden wir ein paar Mal in diese Welt geschickt, aber ... wir hatten kein Mitspracherecht."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Certes, nous avons été envoyées dans ce monde plusieurs fois après cela, mais... nous n'avons jamais eu notre mot à dire."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
