L44_1.m_Face = "UNIT_IDLE"
L44_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L44_1.m_Pos = "C"
L45_1 = "시영 씨 말이 맞아요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "シノンさんの言うとおりです。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You're right."
L44_1.m_Talk_ENG = L45_1
L45_1 = "你說的沒錯。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เธอพูดถูก"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cô nói đúng."
L44_1.m_Talk_VTN = L45_1
L45_1 = "你说得没错。"
L44_1.m_Talk_SCN = L45_1
L44_1.m_Talk_DEU = "Du hast recht, Shiyoung."
L45_1 = "Vous avez raison."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 31612
L45_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L45_1.m_Pos = "C"
L46_1 = "우리가 가진 기술과 자원으로는 다시 그 세계에 도달할 수 있다는 보장이 없어요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "私たちが持っている技術と資源では、またあの世界に到達できるという保証がありません。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "With the technology and resources we possess, there's no guarantee of reaching that world again."
L45_1.m_Talk_ENG = L46_1
L46_1 = "我無法保證使用我們的技術和資源能再次達到那個世界。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ด้วยเทคโนโลยีและทรัพยากรที่เรามี จึงไม่รับประกันว่าจะได้เข้าถึงโลกนั้นอีกครั้ง"
L45_1.m_Talk_THA = L46_1
L46_1 = "Với công nghệ và tài nguyên mà chúng ta sở hữu, không có gì đảm bảo chúng ta có thể đến được thế giới đó lần nữa."
L45_1.m_Talk_VTN = L46_1
L46_1 = "我无法保证使用我们的技术和资源能再次达到那个世界。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Mit der Technologie und den Ressourcen, die wir besitzen, gibt es keine Garantie, diese Welt wieder zu erreichen."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Avec la technologie et les ressources que nous possédons, il n'y a aucune garantie que nous atteindrons ce monde à nouveau."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 31612
L46_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L46_1.m_Pos = "C"
L46_1.m_Crash = 30
L47_1 = "그래서 이번에는 관점을 바꿔서 아티팩트의 힘을 빌려보려는 거죠."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ですから、今回は視点を変えて、アーティファクトの力を借りてみようとしているのです。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "So this time, I'm attempting to approach it from a different angle and use the power of an Artifact."
L46_1.m_Talk_ENG = L47_1
L47_1 = "所以，這次我想換一個角度，就是借用人造神器的力量。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "คราวนี้ ฉันกำลังพยายามเข้าใกล้มันจากมุมที่แตกต่าง และใช้พลังของอาร์ติแฟกต์ "
L46_1.m_Talk_THA = L47_1
L47_1 = "Vì vậy, lần này, tôi đang cố gắng tiếp cận nó từ một góc độ khác và sử dụng sức mạnh của một Thần Khí."
L46_1.m_Talk_VTN = L47_1
L47_1 = "所以，这次我想换一个角度，就是借助人造神器的力量。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Dieses Mal versuche ich also, es aus einem anderen Blickwinkel zu betrachten und die Kraft eines Artefakts zu nutzen."
L46_1.m_Talk_DEU = L47_1
L47_1 = "C'est pourquoi, cette fois, j'essaie d'aborder la situation sous un angle différent et d'utiliser la puissance d'un artefact."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
