L50_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 31612
L49_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "UNIT_LAUGH"
L49_1.m_Face = L50_1
L49_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L49_1.m_Pos = "R"
L49_1.m_Crash = 20
L50_1 = "하하, 왠지 기술로 안 되니까, 주술로 빠지는 것 같은 느낌인데요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ハハ、技術ではうまくいかないから、だんだん呪術にハマっていきそうな感じですけど。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Ha ha, it kinda sounds like you're falling back on voodoo since our technology wasn't enough."
L49_1.m_Talk_ENG = L50_1
L50_1 = "哈哈，聽起來像是技術不太行，就換魔法試試看呢。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฮ่า ฮ่า ดูเหมือนเธอจะหวนคิดถึงวูดูอีกครั้งเพราะเทคโนโลยีของเรายังไม่เพียงพอ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Ha ha, có vẻ như cô đang sa vào tà thuật vì công nghệ của chúng ta chưa đủ."
L49_1.m_Talk_VTN = L50_1
L50_1 = "哈哈，听起来像是技术不太行，魔法来凑呢。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Haha, es hört sich irgendwie so an, als würdest du auf schwarze Magie zurückgreifen, da unsere Technologie nicht ausreicht."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Ha ha, on dirait bien que vous vous tournez vers le vaudou car notre technologie ne suffit pas."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 31612
L50_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_Face = "UNIT_IDLE"
L50_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L50_1.m_Pos = "R"
L51_1 = "하긴 뭐, 절벽에서 떨어지기 직전에 손에 잡히는 게 지푸라기뿐이라면, 일단 그거라도 잡고 봐야지 어쩌겠어요?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "確かにまあ、溺れる前に掴めるものが藁しかなかったら、とりあえずそれでも掴んどかないといけませんから。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Well, desperate times call for desperate measures."
L50_1.m_Talk_ENG = L51_1
L51_1 = "不過也對，就把這當作是我們世界的救命稻草吧？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เวลาที่สิ้นหวังเรียกร้องให้มีมาตรการที่สิ้นหวัง"
L50_1.m_Talk_THA = L51_1
L51_1 = "Chà, những lúc tuyệt vọng đòi hỏi những biện pháp tuyệt vọng."
L50_1.m_Talk_VTN = L51_1
L51_1 = "不过也对，如果摔下悬崖的时候只抓到了一根稻草，那就只能先抓着咯？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Nun ja, wenn alles, woran man sich kurz vor dem Sturz von einer Klippe festhalten kann, ein Strohhalm ist, warum sollte man dann nicht einfach zuerst danach greifen?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Eh bien, les temps désespérés appellent à des mesures désespérées."
L50_1.m_Talk_FRA = L51_1
