L2_1 = "혹시 또 모르는 거죠. 지푸라기인 줄 알고 잡았는데, 그게 동아줄일 수도 있잖아요?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "それに、藁だと思って掴んだものがロープかもしれませんしね？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Who knows? This might actually be our way out."
L1_1.m_Talk_ENG = L2_1
L2_1 = "或許真能死馬當活馬醫？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ใครจะรู้? นี่อาจเป็นทางออกของเราจริงๆ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Ai biết được? Đây thực sự có thể là lối thoát của chúng ta."
L1_1.m_Talk_VTN = L2_1
L2_1 = "或许你以为抓的是稻草，但说不定是根救命的绳子啊？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Wer weiß? Vielleicht ist das, wonach man greift, überhaupt kein Strohhalm, sondern eher ein Seil."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Qui sait ? Cela pourrait s'avérer être notre porte de sortie."
L1_1.m_Talk_FRA = L2_1
