L3_1 = "후후. 오랜만에 마음이 통했네요, 시영 씨."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "ふふ。久しぶりに心が通じましたね、シノンさん。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Hu hu. I'm glad we're in agreement."
L2_1.m_Talk_ENG = L3_1
L3_1 = "呵呵，久違的默契呢，時雨。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ฮู ฮู. ฉันดีใจที่เราตกลงกันได้"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ha ha. Tôi rất vui vì chúng ta đã thống nhất."
L2_1.m_Talk_VTN = L3_1
L3_1 = "呵呵，好久没这么默契了，时雨。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Haha. Endlich sind wir zwei mal einer Meinung, Shiyoung."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Hu hu. Je suis contente de voir que nous sommes enfin sur la même longueur d'onde."
L2_1.m_Talk_FRA = L3_1
