L9_1 = "어, 어어……? 시영 씨!! 저 고양이가 물고 있는 거 보여요!?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "え、ええっ……？　シノンさん！！　あの猫がくわえてるもの、見えますか！？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Uh... Wait...! Shiyoung! Do you see that? In the cat's mouth!"
L8_1.m_Talk_ENG = L9_1
L9_1 = "呃呃……？時雨！你有看到那個小貓叼著的東西嗎？！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เอ่อ...เดี๋ยว...! ชิยอง! เธอเห็นสิ่งนั้นไหม? ในปากเจ้าแมว!"
L8_1.m_Talk_THA = L9_1
L9_1 = "Ờ... Đợi đã...! Shiyoung! Cô có thấy không? Trong miệng con mèo!"
L8_1.m_Talk_VTN = L9_1
L9_1 = "呃呃……？时雨！你看到那个小猫叼着的东西了吗？！"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Äh ... Moment mal ...! Shiyoung! Siehst du, was die Katze im Mund hat?!"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Mais...? Charlotte ! Vous voyez ça ? Dans la gueule du chat ?!"
L8_1.m_Talk_FRA = L9_1
