L10_1.m_Bounce = L11_1
L11_1 = "아뇨!! 저기, 끈으로 꼬리표가 달려있잖아요! 저게 아티팩트 보증서일 거예요!!"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "いいえ！！　ほら、紐でタグが付いてるではないですか！　あれがアーティファクトの保証書のはずです！！"
L10_1.m_Talk_JPN = L11_1
L11_1 = "No!! That tag, at the end of the string! That should be the warranty certificate for the Artifact!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "不！你看，那是標籤！那應該就是人造神器的保證書！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ไม่น่ะ!! เนื้อเรื่องนั้นอยู่ท้ายบทสิ! มันควรจะเป็นใบรับประกันของอาร์ติแฟกต์"
L10_1.m_Talk_THA = L11_1
L11_1 = "KHÔNG!! Cái tag đó, ở cuối cái dây! Đó hẳn là giấy chứng nhận bảo đảm cho Thần Khí!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "不！你看，那是标签！那应该就是人造神器的保证书！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Nein!! Da ist ein Etikett an der Schnur befestigt! Das muss die Garantie des Artefakts sein!!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Non ! L'étiquette au bout de la ficelle ! C'est sûrement le certificat de garantie de l'artefact !"
L10_1.m_Talk_FRA = L11_1
