L14_1 = "도, 도망친다! 빨리 가서 잡아와요, 시영 씨!!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "に、逃げるわ！　早く捕まえて来てください、シノンさん！！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I-it's running away! Quick, catch it, Shiyoung!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "牠，牠跑了！快把牠抓回來，時雨！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ม-มันกำลังวิ่งหนี! เร็วเข้า จับเจ้าแมวไว้ ชิยอง!"
L13_1.m_Talk_THA = L14_1
L14_1 = "N-nó đang chạy trốn! Nhanh lên, bắt nó đi, Shiyoung!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "它、它跑了！快去抓回来啊，时雨！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "D-die Katze rennt weg! Fang sie schnell, Shiyoung!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "I-Il s'enfuit ! Vite, attrapez-le, Charlotte !"
L13_1.m_Talk_FRA = L14_1
