L15_1 = "어라, 괜찮겠어요? 제가 아티팩트를 손에 넣어도?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "あれ、いいんですか？　私がアーティファクトを手に入れても。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Oh, are you sure you want me to get my hands on the Artifact first?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "呃，人造神器落到我手裡也沒關係嗎？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "โอ้ะ เธอแน่ใจหรอว่าอยากให้ฉันเจออาร์ติแฟกต์ก่อน?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Ồ, cô có chắc là muốn tôi chạm tay vào Thần Khí trước không?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "呃，人造神器落到我手里也没关系吗？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Oh, bist du sicher, dass ich zuerst das Artefakt in die Hände bekommen soll?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Oh, vous êtes bien sûre que vous voulez que je sois la première à mettre la main sur cet artefact ?"
L14_1.m_Talk_FRA = L15_1
