L18_1 = "Th-that's a bit concerning, but... I can't touch cats!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "是，不太好……可是我對貓毛過敏！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "น-นั่นก็น่ากังวลนิดหน่อย แต่... ฉันแพ้แมว !"
L17_1.m_Talk_THA = L18_1
L18_1 = "Đ-điều đó có hơi đáng lo ngại, nhưng... tôi không thể chạm vào mèo!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "那、那不行啊……可是我对猫毛过敏！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "M-mir wäre es andersherum auch lieber, aber ... ich kann keine Katzen anfassen!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Ça va vous paraître étrange, mais... je ne peux pas toucher les chats !"
L17_1.m_Talk_FRA = L18_1
