L19_1 = "에휴, 하여간 까탈스럽기도 하셔라."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "はあ、ややこしい。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Geez, so fussy."
L18_1.m_Talk_ENG = L19_1
L19_1 = "哀，你的毛還真多。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "หึหึ วุ่นวายจังเลย"
L18_1.m_Talk_THA = L19_1
L19_1 = "Trời ạ, cầu kỳ quá."
L18_1.m_Talk_VTN = L19_1
L19_1 = "唉，你还真是挑剔啊。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Meine Güte, wie kann man nur so pingelig sein."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Décidément, qu'est-ce que vous êtes difficile."
L18_1.m_Talk_FRA = L19_1
