L24_1 = "하하, 강제로 뺏긴 했는데, 이거 어째 돌려달라고 아우성인데요?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "ハハ、無理やり奪ってはきましたけど、なんだか返してほしいってうるさいですよ？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Ha ha, I took it by force, but the cat's eager to get it back."
L23_1.m_Talk_ENG = L24_1
L24_1 = "哈哈，我從小貓那裡搶來了，但牠一直喵喵叫，好像是叫我還給牠的意思？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฮ่า ฮ่า ฉันเผลอจับมันอย่างแรง แต่เจ้าแมวก็อยากแก้แค้นกลับคืน"
L23_1.m_Talk_THA = L24_1
L24_1 = "Ha ha, tôi đã cưỡng chế nó nhưng con mèo đang đòi lấy lại."
L23_1.m_Talk_VTN = L24_1
L24_1 = "唔，虽说从小猫那里抢来了，但它好像很不满意呢？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Haha, ich habe es mit Gewalt an mich genommen, aber die Katze will es anscheinend unbedingt zurückhaben."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Ha ha, je lui ai arraché de force, mais le chat semble impatient qu'on le lui rende."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
