L25_1 = "그런데 이거 대체 어떻게 여는 거지?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "でもこれ、いったいどうやって開けるんだろう？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "How do I open this thing, anyway?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "不過這是要怎麼打開？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "แล้วฉันจะเปิดเจ้านี่ยังงัย?"
L24_1.m_Talk_THA = L25_1
L25_1 = "Dù sao thì làm sao để mở thứ này?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "总之该怎么打开这个？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Wie öffnet man dieses Ding überhaupt?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Comment ça s'ouvre, d'abord ?"
L24_1.m_Talk_FRA = L25_1
