L28_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 31612
L27_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_IDLE"
L27_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L27_1.m_Pos = "C"
L28_1 = "안 돼요. 고양이보다 사람이 먼저에요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ダメです。猫より人が先です。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "No. People come first, before cats."
L27_1.m_Talk_ENG = L28_1
L28_1 = "不行，人比貓重要。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ไม่สิ คนต้องมาก่อนแมว"
L27_1.m_Talk_THA = L28_1
L28_1 = "Không. Con người đến trước, trước cả mèo."
L27_1.m_Talk_VTN = L28_1
L28_1 = "不行，人应该优先于猫。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Auf keinen Fall. Menschen kommen vor Katzen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "On ne peut pas faire ça ! Les gens comptent plus que les chats !"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 31612
L28_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "UNIT_PRIDE"
L28_1.m_Face = L29_1
L28_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L28_1.m_Pos = "C"
L28_1.m_Crash = 30
L29_1 = "매정하셔라. 하긴 어차피 여기 계속 있으면 침식파 때문에 위험하니까 구조한 셈 칠까요?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "冷たいなあ。まあ、どうせずっとここにいても侵食波で危ないですから、救助したってことにしますか。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "So cold-hearted. Well, let's just say we rescued the cat since the Corruption ray would be dangerous for it."
L28_1.m_Talk_ENG = L29_1
L29_1 = "真是冷酷。不過一直待在這裡會受到侵蝕波影響，就當是我們救牠一命吧？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ใจเย็นจังเลย สมมติว่าเราช่วยแมวไว้เพราะรังสีคอรัปต์ชั่น แต่มันก็อาจเป็นอันตรายต่อมันอยู่ดี"
L28_1.m_Talk_THA = L29_1
L29_1 = "Thật lạnh lùng. Chà, coi như chúng ta đã cứu được con mèo vì tia Ăn Mòn sẽ gây nguy hiểm cho nó."
L28_1.m_Talk_VTN = L29_1
L29_1 = "嘛，真是冷酷无情。不过，如果一直待在这里会受到侵蚀波影响，就当是我们救了它吧？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "So kaltherzig. Sagen wir einfach, wir haben die Katze gerettet, da es wegen der Verderbniswellen ohnehin zu gefährlich wäre, sie hier zurückzulassen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Quel cœur de pierre. Eh bien, nous n'avons qu'à dire que nous avons sauvé ce chat car le Rayon de Corruption lui serait nocif s'il restait ici."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
