L30_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L30_1.m_Pos = "C"
L30_1.m_Crash = 20
L31_1 = "이게 그 보증서인가, 어디보자……."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "これがその保証書かぁ、どれどれ……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "So this is the warranty certificate. Let's see..."
L30_1.m_Talk_ENG = L31_1
L31_1 = "這就是那個保證書嗎，讓我看看……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "และนี่คือใบรับประกัน มาลุ้นกัน..."
L30_1.m_Talk_THA = L31_1
L31_1 = "Vậy đây là giấy chứng nhận bảo đảm. Để xem nào..."
L30_1.m_Talk_VTN = L31_1
L31_1 = "这就是那个保证书吗，让我看看……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Das ist also die Garantie. Mal sehen ..."
L30_1.m_Talk_DEU = L31_1
L31_1 = "C'est donc ça, le certificat de garantie ? Voyons voir..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 31612
L31_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
