L31_1.m_Pos = "C"
L32_1 = "여기까지 도달한 걸 축하한다, 2등……."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ここまでよくたどり着いたな。おめでとう、2位……"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Congratulations on coming in second..."
L31_1.m_Talk_ENG = L32_1
L32_1 = "恭喜你到達這裡，第二名……"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ยินดีด้วยเข้ารอบสองแล้ว..."
L31_1.m_Talk_THA = L32_1
L32_1 = "Chúc mừng bạn đã về nhì..."
L31_1.m_Talk_VTN = L32_1
L32_1 = "恭喜你到达这里，第二名……"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Gratulation zum zweiten Platz ..."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Félicitations pour votre seconde place..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 31612
L32_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L32_1.m_Pos = "C"
L33_1 = "이 아티팩트의 이름은 원숭이 손……. 소원을 이뤄주는 대신 그에 맞는 대가를 지불해야 한다……?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "このアーティファクトの名前はサルの手……願いを叶える代わりに、それ相応の対価を払わないといけない……？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "This Artifact is called Monkey's Paw... Your wish may be granted, for a price...?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "這個人造神器叫猴爪……它可以用來實現願望，但必須付出相對的代價……？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "อาร์ติแฟกต์นี้เรียกว่าอุ้งมือลิง... ความปรารถนาของเธอมีราคาเท่าไหร่...?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Hiện vật này có tên là Bàn Tay Khỉ... Điều ước của bạn có thể được thực hiện, với một cái giá...?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "这个人造神器叫猴爪……它可以用来实现愿望，但必须付出相应的代价……？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Dieses Artefakt heißt Affenhand ... Es kann einen Wunsch erfüllen, aber man muss dafür einen Preis zahlen ...?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Cet artefact s'appelle la Patte de singe... Il permet d'exaucer un vœu, mais cela aura un prix...?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 31612
L33_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_HATE"
L33_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L33_1.m_Pos = "C"
L33_1.m_Crash = 30
L34_1 = "이거 무슨 행운의 편지 같은 거 아니에요? 아무리 봐도 수상한데?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "これ、なんだか不幸の手紙みたいじゃないですか？　どう見ても怪しいですけど。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Is this a chain letter or something? It sounds very shady."
L33_1.m_Talk_ENG = L34_1
L34_1 = "這不會是什麼漂流瓶之類的吧？總覺得很可疑？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "นี่เป็นจดหมายลูกโซ่หรืออะไร? มันฟังดูเรียบมาก"
L33_1.m_Talk_THA = L34_1
L34_1 = "Đây là thư dây chuyền à? Nghe có vẻ rất mờ ám."
L33_1.m_Talk_VTN = L34_1
L34_1 = "这不会是什么漂流瓶之类的吧？总觉得很可疑啊？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ist das eine Art Kettenbrief? Es klingt ziemlich seltsam."
L33_1.m_Talk_DEU = L34_1
L34_1 = "On dirait une de ces chaînes de lettres maudites, ou quelque chose du genre. En tout cas, ça a l'air louche."
L33_1.m_Talk_FRA = L34_1
