L36_1.m_Face = "UNIT_IDLE"
L36_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L36_1.m_Pos = "L"
L36_1.m_Crash = 20
L37_1 = "아니요. 제가 들었던 정보랑 일치해요. 아티팩트가 틀림없어요, 그거."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "いいえ。私が聞いた情報と一致しています。アーティファクトに間違いありません。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "No. It's consistent with the intel I received. That's definitely an Artifact."
L36_1.m_Talk_ENG = L37_1
L37_1 = "不，這和我聽到的情報一致，那個肯定就是人造神器。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ไม่ มันไม่เหมือนกับข้อมูลที่ฉันได้รับ นั่นเป็นอาร์ติแฟกต์อย่างแน่นอน"
L36_1.m_Talk_THA = L37_1
L37_1 = "Không. Nó khớp với thông tin tôi nhận được. Đó chắc chắn là một Thần Khí."
L36_1.m_Talk_VTN = L37_1
L37_1 = "不，这和我听到的情报一致。那个肯定就是人造神器。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Nein. Es stimmt mit den Informationen überein, die ich erhalten habe. Das ist definitiv ein Artefakt."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Non, ça correspond à l'information que j'ai reçue. C'est bien l'artefact, aucun doute là-dessus."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
