L40_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 31612
L39_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_IDLE"
L39_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L39_1.m_Pos = "C"
L40_1 = "그래서 카린 양은 이 아티팩트를 어떻게 쓸 생각일까나?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "それで、カリンさんはこのアーティファクトをどう使う気なのかな？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "So, how are you planning to use this Artifact, Karin?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "那你準備怎麼使用這個人造神器？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "แล้วเธอวางแผนที่จะใช้อาร์ติแฟกต์นี่ยังไง คาริน?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Vậy cô dự định sử dụng Thần Khí này như thế nào, Karin?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "那你准备怎么使用这个人造神器？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Also, was hast du jetzt mit diesem Artefakt vor, Karin?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Alors, comment prévoyez-vous d'utiliser cet artefact, Karin ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 31612
L40_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "UNIT_PRIDE"
L40_1.m_Face = L41_1
L40_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L40_1.m_Pos = "C"
L40_1.m_Crash = 20
L41_1 = "그 꼼꼼한 카린 양이 이런 아티팩트에 집착하는 거 보면, 분명히 대가에 대한 대책이 있겠죠?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "几帳面なカリンさんがこんなアーティファクトに執着してるところを見ると、対価についても策は考えてあるんですよね？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "You must have a solution for the \"price\" if someone as meticulous as you is obsessing over this Artifact."
L40_1.m_Talk_ENG = L41_1
L41_1 = "像卡琳那麼細心的人會執著於這個人造神器，應該早就已經想好要如何應付所謂的代價吧？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เธอต้องมีวิธีแก้ปัญหาของ \"ราคา\" หากมีใครบางคนที่ตั้งใจและหมกมุ่นอยู่กับอาร์ติแฟกต์เหมือนเธออยู่ "
L40_1.m_Talk_THA = L41_1
L41_1 = "Cô hẳn có giải pháp về \"cái giá' nếu một người tỉ mỉ như cô đang bị ám ảnh bởi Thần Khí này."
L40_1.m_Talk_VTN = L41_1
L41_1 = "像卡琳那么细心的人会执着于这个人造神器，肯定已经想好如何应对那个“代价”了吧？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Wenn man bedenkt, wie akribisch du dich mit diesem Artefakt beschäftigt hast, weißt du doch bestimmt, wie man diesen „Preis“ umgehen kann, oder?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "J'imagine que si une personne aussi méticuleuse que vous est tant obsédée par cet artefact, c'est que vous avez une solution quant au « prix » à payer."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
