L43_1.m_Pos = "L"
L43_1.m_Crash = 20
L44_1 = "물론이죠. 저는 머릿속에 놀 생각만 가득한 누구와는 다르다고요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "もちろんです。遊ぶことだけしか考えていない誰かさんとは違いますから。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Of course. Unlike someone, my head isn't filled with how to spend my free time."
L43_1.m_Talk_ENG = L44_1
L44_1 = "當然，我可不像某人，滿腦子只想著玩。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แน่นอน ต่างจากคนอื่น หัวของฉันไม่ได้ว่างตลอด"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tất nhiên rồi. Không giống ai đó, đầu tôi không phải bận tâm đến việc dùng thời gian rảnh như thế nào."
L43_1.m_Talk_VTN = L44_1
L44_1 = "当然了。我可不像某个人，满脑子只想着玩。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Natürlich. Im Gegensatz zu einer gewissen anderen Person, denke ich nicht nur ans Herumalbern."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Bien évidemment. Contrairement à quelqu'un, ma tête n'est pas remplie d'idées sur comment passer mon temps libre."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 31612
L44_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_DESPAIR"
L44_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L44_1.m_Pos = "R"
L45_1 = "네? 그게 누구일까나? 저는 잘 모르겠는데요?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ええ？　それって誰ですか？　全然心当たりがないなあ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Huh? I wonder who that is. I have no idea."
L44_1.m_Talk_ENG = L45_1
L45_1 = "哈哈哈？你是指誰？我怎麼有聽沒有懂？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ฮะ? ฉันสงสัยว่านั่นคือใครกัน ฉันไม่รู้เลย"
L44_1.m_Talk_THA = L45_1
L45_1 = "Hở? Tôi tự hỏi đó là ai. Tôi không biết luôn."
L44_1.m_Talk_VTN = L45_1
L45_1 = "啊哈哈哈？你指的是谁呢？我一点儿都听不明白哦？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Hä? Ich frage mich, wer damit gemeint ist. Ich habe überhaupt keine Ahnung, wer das sein könnte."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Hein ? Je me demande bien de qui vous parlez. Aucune idée, vraiment."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
