L46_1.m_Face = "UNIT_HATE"
L46_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L46_1.m_Pos = "C"
L47_1 = "흥! 당연히 시영 씨죠, 여기 저 말고 시영 씨 밖에 더 있어요?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "フン！　もちろんシノンさんですよ。ここには私以外、シノンさんしかいないではないですか。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Hmph! It's you! Who else is here?!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "哼！當然是你，這裡除了我以外就只有你。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ฮึ่ม! ก็เธอไง! มีใครอยู่ที่นี่อีกหรอ?!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Hừm! Là cô chứ còn ai ở đây nữa?!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "哼！当然是你了，这里除了我以外就只有你了。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Hmpf! Natürlich bist du gemeint, Shiyoung! Wer ist sonst noch hier?!"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Pff ! C'est vous, Charlotte ! Qui d'autre ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 31612
L47_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L47_1.m_bWaitClick = false
L48_1 = 0.3
L47_1.m_fWaitTime = L48_1
L48_1 = "UNIT_PRIDE"
L47_1.m_Face = L48_1
L48_1 = "m_fFlashBangTime"
L49_1 = 0.5
L47_1[L48_1] = L49_1
L48_1 = "FX_COMBAT_ALL_MAGIC_SPELL_02"
L47_1.m_StartFXSoundName = L48_1
L47_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L47_1.m_Pos = "C"
L48_1 = "시영 씨라면, <color=#ffd34c>놀이 공원 같은 곳에서 실컷 놀고 싶다</color>같이 쓸데없는……."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "シノンさんなら、<color=#ffd34c>遊園地とかで思いっきり遊びたい</color>、みたいなくだらない……"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I'm sure your head is filled with useless thoughts like, \"<color=#ffd34c>I want to go somewhere like a theme park,</color>\" and–"
L47_1.m_Talk_ENG = L48_1
L48_1 = "如果是時雨，一定會說什麼<color=#ffd34c>想在遊樂園盡情玩耍</color>這種沒用的……"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฉันแน่ใจว่าหัวของเธอเต็มไปด้วยความคิดที่ไร้สาระเช่น \"<color=#ffd34c>ฉันอยากไปสวนสนุก</color>\" และ–"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi chắc rằng đầu cô đang tràn ngập những suy nghĩ vô ích như \"<color=#ffd34c>Tôi muốn đi đâu đó như công viên giải trí,</color>\" và–"
L47_1.m_Talk_VTN = L48_1
L48_1 = "如果是时雨，一定会说什么<color=#ffd34c>“想在游乐园尽情地游玩”</color>这种没用的……"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich bin mir sicher, dein Kopf ist voller nutzloser Gedanken wie „<color=#ffd34c>Ich möchte irgendwo Spaß haben, zum Beispiel in einem Themenpark</color>“ ..."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je suis sûre que votre tête est remplie de pensées inutiles du genre <color=#ffd34c>Je veux aller m'amuser au parc d'attraction</color>, ou d'autres bêtises du genre..."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
