L6_1 = "어, 어어……!? 멈춰요, 시영 씨!! 그 케이스 함부로 열 면……!!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "え、ええっ……！？　待ってください、シノンさん！！　そのケース、むやみに開けたら……！！"
L5_1.m_Talk_JPN = L6_1
