L5_1.m_Talk_VTN = L6_1
L6_1 = "呃、呃呃……？！停下来，时雨！不要让那个盒子打开……！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Hm? Was?! Hör auf, Shiyoung! Wenn du die Schachtel so unbedacht öffnest, dann –"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Ooh...?! Arrêtez, Charlotte ! N'ouvrez pas cette boît─"
L5_1.m_Talk_FRA = L6_1
