L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "L"
L11_1 = "……그래서 눈을 떠보니, 유령의 집이었다?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "……そして目覚めてみると、お化け屋敷だったと？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "...And you woke up in this haunted house?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "……所以你一睜開眼，就發現自己在鬼屋裡？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "...แล้วเธอก็ตื่นขึ้นมาในบ้านผีสิงนี่นะเหรอ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "...Và cô tỉnh dậy trong ngôi nhà ma ám ám này?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "……所以你一睁眼，就发现自己在鬼屋里了？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "... Als du dann deine Augen geöffnet hast, warst du in diesem Spukhaus?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Et vous vous êtes réveillée dans cette maison hantée...?"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 31612
L11_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "KYLE_DELTA_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "L"
L12_1 = 40
L11_1.m_Crash = L12_1
L12_1 = "제가 그런 헛소리를 믿을 것 같습니까!?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "僕がそんなことを信じるとでも思っているのですか！？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Did you think I'd fall for such nonsense?!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "你以為我會相信你的鬼話嗎？！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "คิดว่าผมหลงกลเรื่องไร้สาระขนาดนี้เหรอ?!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Cô tưởng tôi sẽ tin vào thứ vô lý như vậy à?!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "你以为我会相信你说的话吗？！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Glaubst du wirklich, dass ich dir diesen Unsinn abkaufe?!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Vous pensiez vraiment que j'allais croire à de pareilles sottises ?!"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 31612
L12_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "UNIT_SERIOUS"
L12_1.m_Face = L13_1
L13_1 = "KYLE_DELTA_APHALLOWEEN_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "R"
L13_1 = 40
L12_1.m_Crash = L13_1
L13_1 = "믿기 힘든 건 맞지만, 사실이라고요!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "信じ難いのは事実ですけど、本当なんです！"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I know it's not very believable, but it's true!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "我知道這很難讓人相信，但我說的都是真的！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ฉันรู้ว่ามันไม่ค่อยน่าเชื่อแต่มันเป็นเรื่องจริง!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tôi biết là không đáng tin lắm, nhưng đó là sự thật!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "我知道这很难让人相信，但我说的都是真话！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ich weiß, dass es schwer zu glauben ist, aber es ist die Wahrheit!"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Je sais que ce n'est pas très crédible, mais c'est la vérité !"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 31612
L13_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_DESPAIR"
L14_1 = "KYLE_DELTA_APHALLOWEEN_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "R"
L14_1 = "그렇게 눈을 뜬 저는 관리국 스탭들의 배려로 이곳 고스트 하우스에서 일하게 되었지만……."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "そうして目覚めた私は、管理局スタッフの計らいでこのゴーストハウスで働けることになったのですが……"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I woke up, and started working here thanks to the generosity of the staff members of the Administration, but..."
L13_1.m_Talk_ENG = L14_1
L14_1 = "當時多虧有管理局工作人員的關照，才能在這個鬼屋工作……"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฉันตื่นมาก็ได้ทำงานที่นี่ ด้วยความมีน้ำใจของเจ้าหน้าองค์การบริหารโลก แต่..."
L13_1.m_Talk_THA = L14_1
L14_1 = "Tôi tỉnh dậy và bắt đầu làm việc ở đây nhờ vào sự hào phóng của các nhân viên của Cục Quản Lý, nhưng..."
L13_1.m_Talk_VTN = L14_1
L14_1 = "当时多亏了管理局工作人员的关照，才能在这个鬼屋工作……"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich bin aufgewacht und habe dank der Großzügigkeit der Mitarbeiter der Administration hier angefangen zu arbeiten, aber ..."
L13_1.m_Talk_DEU = L14_1
L14_1 = "C'est comme ça que je me suis réveillée ici, et si j'ai pu commencer à travailler, c'est grâce à la générosité du personnel de l'Administration, cependant..."
L13_1.m_Talk_FRA = L14_1
