L18_1 = 40
L17_1.m_Crash = L18_1
L18_1 = "여, 역시…… 유, 유령의 집은…… 좀……."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "や、やはり……お、お化け屋敷は……ちょっと……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "A-a... h-haunted house is... a bit..."
L17_1.m_Talk_ENG = L18_1
L18_1 = "果，果然……鬼，鬼屋……有點……"
L17_1.m_Talk_TWN = L18_1
L18_1 = "อ๊า... บ้านผีสิงก็... นิดหน่อย..."
L17_1.m_Talk_THA = L18_1
L18_1 = "Aa... h-ngôi nhà ma ám... hơi..."
L17_1.m_Talk_VTN = L18_1
L18_1 = "果、果然……鬼、鬼屋……有点……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "I-ich wusste es ... Ein gruseliges G-Geisterhaus ist ... ein bisschen ..."
L17_1.m_Talk_DEU = L18_1
L18_1 = "U-Une maison hantée... C-C'est un peu..."
