L20_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 31612
L19_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_IDLE"
L20_1 = "KYLE_DELTA_APHALLOWEEN_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "C"
L20_1 = "하지만 이곳에서 일하는 동안 당초 목표였던 관리국의 최신 기술력을 관찰할 수 있었어요."
L19_1.m_Talk_KOREA = L20_1
L20_1 = 0.04
L19_1.m_fTalkTime = L20_1
L20_1 = "でもここで働く間に、当初の目的だった管理局の最新技術力を観察することができました。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "But I was able to observe the state-of-the-art technology of the Administration while working here."
L19_1.m_Talk_ENG = L20_1
L20_1 = "但在這裡工作的時候，我得以觀察到管理局的最新技術，那也是我當初的目的。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "แต่ฉันสามารถสังเกตเห็นเทคโนโลยีล้ำสมัยขององค์การบริหารโลกได้ในขณะที่ได้ทำงานที่นี่ "
L19_1.m_Talk_THA = L20_1
L20_1 = "Nhưng tôi đã có thể quan sát công nghệ tiên tiến của Cục Quản lý khi làm việc ở đây."
L19_1.m_Talk_VTN = L20_1
L20_1 = "但在这里工作的时候，我得以观察到管理局的最新技术，那也是我当初的目的。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Aber ich konnte während meiner Arbeit hier die hochmoderne Technologie der Administration genauer unter die Lupe nehmen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Quoi qu'il en soit, j'ai pu observer la technologie de pointe de l'Administration en travaillant ici."
L19_1.m_Talk_FRA = L20_1
