L23_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 31612
L22_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_DESPAIR"
L23_1 = "KYLE_DELTA_APHALLOWEEN_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "R"
L22_1.m_Crash = 20
L23_1 = "물론, 대부분은 제 능력으로도 이해할 수 없는 고차원의 기술이었지만요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "もちろん、ほとんどは私の能力でも理解できない、ハイテクでしたけど。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Of course, most of it was highly advanced, and I could not comprehend it, even with my abilities."
L22_1.m_Talk_ENG = L23_1
L23_1 = "當然，大部分的高端技術，單憑我的能力是根本無法理解的。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "แน่นอน ว่าส่วนมากมันมีความก้าวล้ำที่สูงมาก และฉันก็ไม่สามารถเข้าใจมันได้ แม้จะมีความสามารถก็ตาม"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tất nhiên, hầu hết đều ở trình độ cao và tôi không thể hiểu được nó, ngay cả với khả năng của mình."
L22_1.m_Talk_VTN = L23_1
L23_1 = "当然，大部分的高端技术，仅凭我的能力是根本无法理解的。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Natürlich war das meiste davon sehr fortgeschritten und ich konnte es trotz meiner Fähigkeiten nicht verstehen."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Bien sûr, la majeure partie de cette technologie est tellement avancée que je n'ai pas réussi à en saisir tous les aspects, malgré mes capacités."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 31612
L23_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "UNIT_SERIOUS"
L23_1.m_Face = L24_1
L24_1 = "KYLE_DELTA_NULL_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "L"
L24_1 = 40
L23_1.m_Crash = L24_1
L24_1 = "가지가지 하는군요. 쓰레기 무단 투기에 이어서, 이번에는 산업 스파이입니까?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "呆れましたね。ゴミの不法投棄に、今度は産業スパイですか？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "It's always one thing after another. First, you illegally dispose of trash, and now you're engaging in industrial espionage?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "你還真忙，之前來這裡亂扔垃圾，現在又當起間諜？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "มันเป็นสิ่งเดียวหลังจากหลายสิ่ง อันดับแรก เธอทิ้งขยะอย่างผิดกฎหมาย และตอนนี้เธอก็กำลังจะมีส่วนร่วมในการโจรกรรมทางอุตสาหกรรมด้วยใช่ไหม?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Lúc nào cũng là hết việc này tới việc khác. Đầu tiên, cô vứt rác trái phép, và giờ cô đang dính tới làm gián điệp công nghiệp?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "你的事情真多啊。之前来这里乱扔垃圾，现在又当起间谍来了？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Immer schön der Reihe nach. Zuerst entsorgst du illegal Müll, und jetzt betreibst du auch noch Industriespionage?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Vous ne manquez jamais de me surprendre. D'abord vous disposez illégalement de vos déchets et maintenant vous vous adonnez à de l'espionnage industriel."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
