L26_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@175#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 31612
L25_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "UNIT_SERIOUS"
L25_1.m_Face = L26_1
L26_1 = "KYLE_DELTA_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L25_1.m_Crash = 20
L26_1 = "제가 전에 말했었죠? 법정에서 당신들의 죗값을 치르게 하겠다고."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "前に言いましたよね。法廷であなたたちの罪を問うと。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I told you. I'll make you pay for your crimes in court."
L25_1.m_Talk_ENG = L26_1
L26_1 = "我之前說過吧？我會讓你們在法庭伏法認罪。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ผมบอกแล้ว ว่าจะทำให้ต้องชดใช้ความผิดในศาล"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi đã nói với cô rồi. Tôi sẽ bắt cô phải trả giá cho tội của mình trước tòa."
L25_1.m_Talk_VTN = L26_1
L26_1 = "我之前说过吧？我会让你们在法庭伏法认罪。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ich habe es dir doch schon gesagt, oder? Ich werde dich vor Gericht für deine Verbrechen büßen lassen."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Je vous l'avais dit, n'est-ce pas ? Que je vous ferai payer pour vos crimes devant le tribunal."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 31612
L26_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L26_1.m_bWaitClick = true
