L26_1.m_Face = "UNIT_HATE"
L27_1 = "KYLE_DELTA_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L27_1 = 40
L26_1.m_Crash = L27_1
L27_1 = "오늘이야말로 그때인 것 같군요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "今日がその日のようですね。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "And it seems like today is that day."
L26_1.m_Talk_ENG = L27_1
L27_1 = "看來就是今天。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "และดูเหมือนว่าวันนี้จะเป็นในวันนั้น"
L26_1.m_Talk_THA = L27_1
L27_1 = "Và có vẻ như hôm nay chính là ngày đó."
L26_1.m_Talk_VTN = L27_1
L27_1 = "看来今天就是那个时候。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Und es scheint, als wäre heute dieser Tag."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Et il semblerait que ce jour soit arrivé."
L26_1.m_Talk_FRA = L27_1
