L31_1 = "UNIT_SERIOUS"
L30_1.m_Face = L31_1
L31_1 = "KYLE_DELTA_APHALLOWEEN_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "R"
L31_1 = "좋아요. 법정에 서겠습니다. 하지만 제 선택에 후회는 없어요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "いいでしょう。法廷に立ちます。ですが、自分の選択に悔いはありません。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Very well. I'll see you in court. But I regret nothing from my decisions."
L30_1.m_Talk_ENG = L31_1
L31_1 = "好，我願意出庭。但我不後悔我的選擇。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ดีหล่ะ ฉันจะไปพบนายในศาล แต่ฉันไม่คิดเสียใจเลยกับการตัดสินใจของฉัน"
L30_1.m_Talk_THA = L31_1
L31_1 = "Được thôi. Tôi sẽ gặp cậu ở tòa án. Nhưng tôi không hối tiếc gì về những quyết định của mình."
L30_1.m_Talk_VTN = L31_1
L31_1 = "好，我愿意出庭。但我不后悔我的选择。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Also gut. Wir sehen uns vor Gericht. Aber ich bereue keine meiner Entscheidungen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Très bien. J'irai au tribunal. Mais sachez que je ne regrette aucun de mes choix."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 31612
L31_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_PRIDE"
L31_1.m_Face = L32_1
L32_1 = "KYLE_DELTA_APHALLOWEEN_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "R"
L32_1 = "제발로 법정에 서서 죗값을 치룬 뒤, 사정을 설명하고 관리국에게 정식으로 기술원조를 부탁드려보겠습니다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "自分の足で法廷に立って罪を償った後に、事情を説明して管理局に正式な技術援助を頼んでみます。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I'll go to court, pay for my crimes, explain the situation, and ask the Administration for their official technical aid."
L31_1.m_Talk_ENG = L32_1
L32_1 = "我會親自出庭接受審判，然後說明情況，並請求管理局正式進行技術援助。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฉันจะไปขึ้นศาล ชดใช้ความผิดของฉัน อธิบายสถานการณ์ และขอความช่วยเหลือด้านเทคโนโลยีอย่างเป็นทางการจากองค์การบริการโลก"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi sẽ ra tòa, trả giá cho tội của mình, giải thích tình hình và nhờ Cục Quản Lý hỗ trợ kỹ thuật chính thức."
L31_1.m_Talk_VTN = L32_1
L32_1 = "我会亲自出庭接受审判，然后说明情况，并请求管理局正式进行技术援助。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich werde vor Gericht gehen, für meine Verbrechen bezahlen, die Situation erklären und die Administration um offizielle technische Unterstützung bitten."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Je me rendrai au tribunal et je paierai pour mes crimes. Puis j'expliquerai la situation et demanderai à l'Administration leur aide technique officielle."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 31612
L32_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_IDLE"
L33_1 = "KYLE_DELTA_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "L"
L33_1 = "흥, 지금까지의 당신의 행동이 썩 마음에 들지는 않지만……."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "フン、今までのあなたの行動はあまり気に入りませんが……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Hmph, I don't really like what you've done so far..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "哼，雖說我不是很滿意你一直以來的所作所為……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ฮึ่ม ผมยังไม่ตื่นเต้นกับการกระทำของเธอมากนักจนมาถึงตอนนี้..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Hừm, cho đến giờ tôi không mấy hứng thú với hành động của cô..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "哼，虽说我不是很满意你一直以来的所作所为……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Hmpf, mir gefällt nicht wirklich, was du bisher gemacht hast, aber ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Humph, je n'apprécie pas ce que vous avez fait jusqu'à présent..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 31612
L33_1.m_CutScenStrID = "COUNTERCASE_DELTA_KYLE_AP_NORMAL_2"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "UNIT_PRIDE"
L33_1.m_Face = L34_1
L34_1 = "KYLE_DELTA_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "L"
L33_1.m_Crash = 20
L34_1 = "뭐, 좋습니다. 군인으로서의 최소한의 책임감만큼은 인정해드리죠."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "まあ、いいでしょう。軍人としての最低限の責任感だけは認めてあげます。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "But, very well. I'll admit, you have the minimal amount of responsibility any soldier should have."
L33_1.m_Talk_ENG = L34_1
L34_1 = "好吧，我承認你有身為軍人的那麼一絲絲責任感。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แต่ก็ดีแล้ว ผมจะยอมรับว่าเธอมีความรับผิดชอบนิดหน่อยที่ทหารทุกคนควรมี"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nhưng, được thôi. Tôi sẽ thừa nhận, cô có trách nhiệm tối thiểu mà bất kỳ người lính nào cũng phải có."
L33_1.m_Talk_VTN = L34_1
L34_1 = "好吧，我承认你有身为军人的那么一丝丝责任感。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Aber gut. Ich gebe zu, dass du das Mindestmaß an Verantwortung trägst, das ein Soldat haben sollte."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Mais, soit. Je dois avouer que vous avez le sens des responsabilités minimal qu'un soldat se doit d'avoir."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
