L39_1 = "저 대신 당신이 이 <color=#ffd34c>유니폼</color>을 스태프분께 전해주세요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "私に代わって、この<color=#ffd34c>ユニフォーム</color>をスタッフの方に渡してもらえますか。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Please hand this <color=#ffd34c>uniform</color> to a staff member for me."
L38_1.m_Talk_ENG = L39_1
L39_1 = "另外，請替我把這個<color=#ffd34c>制服</color>交還給工作人員。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "กรุณามอบ<color=#ffd34c>เครื่องแบบ</color>นี้ให้กับเจ้าหน้าที่ของฉันด้วย"
L38_1.m_Talk_THA = L39_1
L39_1 = "Vui lòng đưa <color=#ffd34c>đồng phục</color> này cho nhân viên giúp tôi."
L38_1.m_Talk_VTN = L39_1
L39_1 = "另外，请替我把这个<color=#ffd34c>制服</color>交还给工作人员。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Bitte gib für mich diese <color=#ffd34c>Uniform</color> einem Mitarbeiter."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Veuillez remettre cet <color=#ffd34c>uniforme</color> à un membre du personnel pour moi."
L38_1.m_Talk_FRA = L39_1
