L43_1 = "이제 그만 좀 하자니까, 실비아. 벌써 1시간 째야."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "もういいだろ、シルビア。探し始めて1時間だぞ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "C'mon, Sylvia. It's been an hour."
L42_1.m_Talk_ENG = L43_1
L43_1 = "到此為止吧，希爾維亞，我們都找一個多小時了。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เอาล่ะ ซิลเวีย ผ่านมาหนึ่งชั่วโมงแล้ว"
L42_1.m_Talk_THA = L43_1
L43_1 = "Thôi nào, Sylvia. Đã một tiếng rồi."
L42_1.m_Talk_VTN = L43_1
L43_1 = "到此为止吧，希尔薇娅。我们都找了一个多小时了。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Komm schon, Sylvia. Es ist schon eine Stunde her."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Allez, Sylvia. Ça fait déjà une heure."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
