L43_1.m_Pos = "R"
L43_1.m_Crash = 30
L44_1 = "부, 분명히 이쪽으로 왔었는데……? 대체 그 빨간 망토는 어디로……."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "た、確かにこっちに来たのに……あの赤ずきん、いったいどこに……"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I-I'm sure she came this way... Where did that Red Riding Hood go...?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "我，我明明看到她往這邊來啦……？那個紅色披風到底去哪啦……"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉัน-ฉันแน่ใจว่าเธอเดินมาทางนี้... หนูน้อยหมวกแดงไปไหนแล้วอ่ะ...?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi chắc chắn cô ấy đã đi theo hướng này... Cô Bé Quàng Khăn Đỏ đã đi đâu...?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "我、我明明看到往这边来了啊……？那个红色披风到底去哪儿了……"
L43_1.m_Talk_SCN = L44_1
L44_1 = "I-ich habe sie definitiv in diese Richtung laufen sehen ... Wo ist das Rotkäppchen bloß hingegangen ...?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "J-Je suis sûre qu'elle est arrivée par ici... Où est donc passé ce Petit Chaperon rouge..."
L43_1.m_Talk_FRA = L44_1
