L2_1 = "아! 실비아 씨, 대령님. 때마침 잘 왔습니다."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "あ！　シルビアさん、大佐。ちょうどいいところに。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Ah! Sylvia, Colonel. Good timing."
L1_1.m_Talk_ENG = L2_1
L2_1 = "喔！希爾維亞，上校，你們來得正好。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "อา! ซิลเวีย ผู้พัน เวลาบังเอิญจัง"
L1_1.m_Talk_THA = L2_1
L2_1 = "Ah! Sylvia, Đại tá. Đúng lúc lắm."
L1_1.m_Talk_VTN = L2_1
L2_1 = "啊！希尔薇娅，上校大人。你们来得正好。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ah! Sylvia, Oberst. Gutes Timing."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Ah ! Sylvia, colonel. Pile au bon moment."
L1_1.m_Talk_FRA = L2_1
