L2_1.m_Crash = 30
L3_1 = "지난 번에 연구 기지를 무단으로 습격한 범인의 신병을 확보했습니다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "この前研究基地を無断襲撃した犯人の身柄を確保しました。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I've apprehended the culprit that ambushed our research facility."
L2_1.m_Talk_ENG = L3_1
L3_1 = "我抓到了上次無故襲擊研究基地的犯人。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ผมมาจับคนร้ายที่ซุ่มโจมตีศูนย์วิจัยของเราได้แล้ว"
L2_1.m_Talk_THA = L3_1
L3_1 = "Tôi đã bắt được thủ phạm phục kích cơ sở nghiên cứu của chúng ta."
L2_1.m_Talk_VTN = L3_1
L3_1 = "我抓到了上次无故袭击研究基地的犯人。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Ich habe die Übeltäterin festgenommen, die letztes Mal unsere Forschungseinrichtung überfallen hat."
L2_1.m_Talk_DEU = L3_1
L3_1 = "J'ai appréhendé le coupable qui a attaqué notre centre de recherche."
L2_1.m_Talk_FRA = L3_1
