L5_1.m_fTalkTime = 0.03
L6_1 = "うん？　犯人？　何を言ってるんだ、カイル？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Huh? Culprit? What are you talking about, Kyle?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "嗯？犯人？你在說什麼，凱爾？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ฮะ? ผู้ร้ายหรอ? นายกำลังพูดถึงเรื่องอะไร ไคล์?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Hả? Thủ phạm? Cậu đang nói về cái gì thế, Kyle?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "嗯？犯人？你在说什么，凯尔？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Hä? Übeltäterin? Wovon redest du, Kyle?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Hein ? Le coupable ? Mais de quoi tu parles, Kyle ?"
L5_1.m_Talk_FRA = L6_1
