L22_1 = "흐으음~ 그래, 그렇구나. 그런 설정이었구나?"
L21_1.m_Talk_KOREA = L22_1
L22_1 = 0.04
L21_1.m_fTalkTime = L22_1
L22_1 = "ふうん～そう、なるほど。そういう設定だったのね？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Hmmm! Okay, all right. \"Working undercover.\" That's your backstory."
L21_1.m_Talk_ENG = L22_1
L22_1 = "嗯嗯嗯～是喔，這樣喔，原來是這種人設喔？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อืม! พอเข้าใจแล้ว \"ทำงานนอกเครื่องแบบ\" นั่นคือเบื้องหลังของนายสินะ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Hừm! Ok, được rồi. \"Hoạt động ngầm.\" Đó là câu chuyện quá khứ của cậu."
L21_1.m_Talk_VTN = L22_1
L22_1 = "唔~是嘛，这样啊。原来是这种人设啊？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Hmmm! Okay, alles klar. „Verdeckt gearbeitet\" ist also deine Hintergrundgeschichte."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Hmmm ! Je vois, je vois. C'est donc ça que tu manigançais ?"
L21_1.m_Talk_FRA = L22_1
