L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "L"
L26_1.m_Crash = 20
L27_1 = "……크, 크흠. 흠!! 그런 취미를 가지고 있었다니, 의외인 걸 카일?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "……こ、こほん。ふむ！！　そういった趣味を持っているとは、意外だな。カイル。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "...Ahem! Errhm! I'm surprised you had this kind of hobby, Kyle."
L26_1.m_Talk_ENG = L27_1
L27_1 = "……咳，咳咳。咳！你居然有那種嗜好，真令人意外，凱爾？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "...อะแฮ่ม! เอ่อ! ผมก็แปลกใจที่นายมีงานอดิเรกแบบนี้ ไคล์"
L26_1.m_Talk_THA = L27_1
L27_1 = "...Àm! Ừm! Tôi ngạc nhiên là cậu lại có sở thích như vậy, Kyle."
L26_1.m_Talk_VTN = L27_1
L27_1 = "……咳、咳咳。咳！你居然有那种爱好，很令人意外啊，凯尔？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "... Ä-ähem! Hmm! Ich bin überrascht, dass du so ein Hobby hattest, Kyle."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Ahem...! Je suis surpris que tu aies ce genre de passe-temps, Kyle."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
