L28_1 = 40
L27_1.m_Crash = L28_1
L28_1 = "하지만 걱정 말라구. 나는 부하의 취향 정도는 존중해주는 편이니까."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "だが、心配するな。俺は部下の好みは尊重してやる方だから。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "But don't worry. I'm pretty accepting of my subordinates' tastes."
L27_1.m_Talk_ENG = L28_1
L28_1 = "但不用擔心，我一向很尊重屬性的興趣的。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "แต่ไม่ต้องกังวลไป ผมยอมรับรสนิยมของลูกน้องเสมอ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Nhưng đừng lo. Tôi khá chấp nhận sở thích của cấp dưới."
L27_1.m_Talk_VTN = L28_1
L28_1 = "但不用担心，我还是很尊重部下的取向的。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Aber keine Sorge. Ich respektiere den Geschmack meiner Untergebenen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Mais ne t'en fais pas. Je suis très tolérant en ce qui concerne les goûts de mes subordonnés."
L27_1.m_Talk_FRA = L28_1
